#!/usr/bin/env python3
# ============================================================================
# refill_controller.py -- mechanical sustained-refill state machine
# Purpose : Own the refill contract between the lifecycle hooks (which observe
#           SubagentStart/SubagentStop/close) and the main agent / scheduler
#           (which holds the host spawn capability).  The controller never
#           calls the host spawn API itself: while pending/ready work exists
#           and active agents are below the low-water mark it writes a
#           machine-readable refill_required record carrying the deficit and
#           model_pool, and it keeps unfulfilled debt fail-visible.  Only
#           observed RUNNING agents count as effective concurrency: idle,
#           completed and shutdown_pending agents never count toward the
#           target, and they surface as reuse/assign suggestions first, then
#           as idle_reclaim_required + host_close_agent_required when they
#           cannot be reused or exceed the configurable idle_reclaim_threshold.
#           No command can claim "refilled" without host action; the record
#           clears only when the work queue empties or an explicit
#           release_finalize is issued.
# Input   : config [agents] normal_wave_concurrency (target),
#           normal_wave_low_water, max_concurrent_threads_per_session (cap);
#           data/refill/work_queue.json (maintained by CLI or ledger sync);
#           data/lifecycle/native_roster.json (running agents by model pool)
# Output  : data/refill/refill_state.json (authoritative, JSON), plus
#           data/refill/events.ndjson (append-only signal for the scheduler).
#           CLI: --status / --recompute / --queue-set / --queue-add /
#           --queue-remove / --queue-clear / --queue-sync-ledger /
#           --spawn-intent / --release-finalize / --resume
# ============================================================================
from __future__ import annotations

import argparse
import contextlib
import json
import os
import sys
import time
from pathlib import Path
from typing import Any

try:
    from loop_config import config_bool, config_int, policy_value
except ImportError:  # pragma: no cover - CLI entry resolves harness/ itself
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from loop_config import config_bool, config_int, policy_value

POOLS = ("v4", "k3")
STATE_SCHEMA = "codex-loop-refill/v2"
QUEUE_SCHEMA = "codex-loop-refill-queue/v1"
RECLAIMABLE_STATUSES = ("idle", "completed", "shutdown_pending")
DEFAULT_TARGETS = {"v4": 16, "k3": 16}
DEFAULT_LOW_WATERS = {"v4": 12, "k3": 12}
DEFAULT_CAP = 50
DEFAULT_MAX_INITIALIZING = 4


def root_path() -> Path:
    return Path(os.environ.get("LOOP_ROOT", Path(__file__).resolve().parents[1])).resolve()


def classify_pool(model: Any) -> str:
    """Route an observed agent model into the v4 or k3 pool."""
    value = str(model or "").lower()
    return "k3" if ("k3" in value or "r1" in value or "reasoner" in value) else "v4"


@contextlib.contextmanager
def lock(path: Path):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a+b") as handle:
        handle.seek(0, os.SEEK_END)
        if handle.tell() == 0:
            handle.write(b"\0")
            handle.flush()
        handle.seek(0)
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(handle.fileno(), msvcrt.LK_LOCK, 1)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".%d.tmp" % os.getpid())
    with tmp.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(value, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def read_json(path: Path, default: Any) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


class RefillController:
    """Mechanical refill state machine (see module docstring)."""

    def __init__(self, root: Path | None = None):
        self.root = (Path(root) if root is not None else root_path()).resolve()
        self.refill_dir = self.root / "data" / "refill"
        self.state_path = self.refill_dir / "refill_state.json"
        self.queue_path = self.refill_dir / "work_queue.json"
        self.events_path = self.refill_dir / "events.ndjson"
        self.lock_path = self.refill_dir / ".refill.lock"
        self.roster_path = self.root / "data" / "lifecycle" / "native_roster.json"
        self.exec_roster_path = self.root / "data" / "lifecycle" / "exec_roster.json"
        self.throttle_state_path = self.refill_dir / "spawn_throttle_state.json"
        self.ledger_path = self.root / "data" / "progress_ledger.json"

    # ---- configuration ------------------------------------------------------
    def target(self, pool: str = "v4") -> int:
        value = policy_value("concurrency", "%s_target" % pool, None, self.root)
        if isinstance(value, int) and not isinstance(value, bool):
            return max(0, value)
        legacy = ("normal_k3_wave_concurrency" if pool == "k3"
                  else "normal_wave_concurrency")
        return max(0, config_int("agents", legacy, DEFAULT_TARGETS[pool], self.root))

    def target_total(self) -> int:
        value = policy_value("concurrency", "target_total", None, self.root)
        if isinstance(value, int) and not isinstance(value, bool):
            return max(0, value)
        return sum(self.target(pool) for pool in POOLS)

    def low_water(self, pool: str = "v4") -> int:
        value = policy_value("concurrency", "%s_low_water" % pool, None, self.root)
        if not isinstance(value, int) or isinstance(value, bool):
            legacy = ("normal_k3_wave_low_water" if pool == "k3"
                      else "normal_wave_low_water")
            value = config_int("agents", legacy, DEFAULT_LOW_WATERS[pool], self.root)
        return min(self.target(pool), value)

    def cap(self) -> int:
        return config_int("agents", "max_concurrent_threads_per_session", DEFAULT_CAP, self.root)

    def max_initializing(self) -> int:
        value = policy_value("spawn_throttle", "max_initializing", None, self.root)
        return max(1, value if isinstance(value, int) and not isinstance(value, bool)
                   else self.cap())

    def idle_reclaim_threshold(self) -> int:
        """Idle agents beyond this count (that cannot be reused) must be
        reclaimed before/while refilling.  Configurable per deployment."""
        return max(0, config_int("agents", "idle_reclaim_threshold", 0, self.root))

    def host_spawn_available(self) -> bool:
        return config_bool("agents", "refill_direct_spawn", False, self.root)

    # ---- work queue -----------------------------------------------------------
    def read_queue(self) -> dict[str, int]:
        doc = read_json(self.queue_path, {})
        pools = doc.get("pools", {}) if isinstance(doc, dict) else {}
        return {p: max(0, int(pools.get(p, 0) or 0)) for p in POOLS}

    def write_queue(self, pools: dict[str, int]) -> dict[str, int]:
        clean = {p: max(0, int(pools.get(p, 0) or 0)) for p in POOLS}
        with lock(self.lock_path):
            self._write_queue_unlocked(clean)
        return clean

    def _write_queue_unlocked(self, clean: dict[str, int]) -> None:
        atomic_json(self.queue_path, {"schema": QUEUE_SCHEMA, "pools": clean,
                                      "updated_at": time.time()})

    def _queue_mutate(self, fn) -> dict[str, int]:
        with lock(self.lock_path):
            pools = self.read_queue()
            fn(pools)
            clean = {p: max(0, int(pools.get(p, 0) or 0)) for p in POOLS}
            self._write_queue_unlocked(clean)
            return clean

    def queue_set(self, count: int, pool: str = "v4") -> dict[str, int]:
        return self._queue_mutate(lambda pools: pools.__setitem__(pool, int(count)))

    def queue_add(self, count: int, pool: str = "v4") -> dict[str, int]:
        return self._queue_mutate(lambda pools: pools.__setitem__(
            pool, pools.get(pool, 0) + int(count)))

    def queue_remove(self, count: int, pool: str = "v4") -> dict[str, int]:
        return self._queue_mutate(lambda pools: pools.__setitem__(
            pool, max(0, pools.get(pool, 0) - int(count))))

    def queue_clear(self) -> dict[str, int]:
        return self.write_queue({p: 0 for p in POOLS})

    def queue_sync_ledger(self, pool: str = "v4") -> dict[str, int]:
        """Count DISPATCHABLE packets from the progress ledger into one pool."""
        led = read_json(self.ledger_path, {"packets": {}})
        ready = sum(1 for item in led.get("packets", {}).values()
                    if isinstance(item, dict) and item.get("state") == "DISPATCHABLE")
        return self._queue_mutate(lambda pools: pools.__setitem__(pool, ready))

    # ---- observed state ---------------------------------------------------------
    def read_roster_state(self) -> tuple[dict[str, dict[str, int]], dict[str, dict[str, list[str]]]]:
        """Combine Desktop-native and headless exec lifecycle state.

        Only ``running`` counts as effective concurrency.  ``idle`` (UI open, no
        active turn), ``completed`` and ``shutdown_pending`` hold host slots but
        never count toward the target. ``initializing`` reserves birth capacity
        but is not effective concurrency. Terminal headless jobs hold no host slot
        and therefore are not added to the reclaimable Desktop counts.
        """
        roster = read_json(self.roster_path, {"agents": {}})
        keys = ("initializing", "running", "idle", "completed", "shutdown_pending")
        counts = {p: {key: 0 for key in keys}
                  for p in POOLS}
        ids = {p: {key: [] for key in keys}
               for p in POOLS}
        for item in (roster.get("agents") or {}).values():
            if not isinstance(item, dict):
                continue
            pool = classify_pool(item.get("model"))
            status = str(item.get("status") or "")
            key = status if status in counts[pool] else None
            if key is None:
                continue
            counts[pool][key] += 1
            aid = item.get("agent_id") or item.get("task_name") or "unknown"
            ids[pool][key].append(str(aid))

        # A PreToolUse birth is initializing until SubagentStart binds it.
        for item in (roster.get("pending") or []):
            if not isinstance(item, dict) or item.get("status") != "pending_start":
                continue
            role = str(item.get("agent_role") or "")
            pool = ("k3" if role in {"verifier", "reviewer"}
                    else classify_pool(item.get("model")))
            aid = item.get("agent_id") or item.get("tool_use_id") or item.get("task_name") or "pending"
            counts[pool]["initializing"] += 1
            ids[pool]["initializing"].append(str(aid))

        # Headless WSL `codex exec` workers are the steady-state execution plane.
        exec_roster = read_json(self.exec_roster_path, {"jobs": {}})
        for item in (exec_roster.get("jobs") or {}).values():
            if not isinstance(item, dict):
                continue
            state = str(item.get("state") or "")
            key = "initializing" if state == "starting" else ("running" if state == "running" else None)
            if key is None:
                continue
            pool = classify_pool(item.get("model"))
            aid = item.get("run_id") or item.get("packet_id") or item.get("task_name") or "exec"
            counts[pool][key] += 1
            ids[pool][key].append(str(aid))
        return counts, ids


    def read_active(self) -> dict[str, int]:
        """Effective concurrency: running agents only, per model pool."""
        counts, _ = self.read_roster_state()
        return {p: counts[p]["running"] for p in POOLS}

    def read_state(self) -> dict[str, Any]:
        return read_json(self.state_path, {"schema": STATE_SCHEMA, "finalized": False,
                                           "refill_required": False})

    # ---- deficit math ------------------------------------------------------------
    @staticmethod
    def split_deficit(total: int, pending: dict[str, int]) -> dict[str, int]:
        """Hamilton (largest remainder) split of the deficit across pools."""
        out = {p: 0 for p in POOLS}
        pools = [p for p in POOLS if pending.get(p, 0) > 0]
        if total <= 0 or not pools:
            return out
        grand = sum(pending[p] for p in pools)
        floors = {p: total * pending[p] // grand for p in pools}
        remainders = {p: total * pending[p] % grand for p in pools}
        remaining = total - sum(floors.values())
        for p in sorted(pools, key=lambda p: remainders[p], reverse=True):
            if remaining <= 0:
                break
            if floors[p] < pending[p]:
                floors[p] += 1
                remaining -= 1
        for p in pools:
            floors[p] = min(floors[p], pending[p])
        for p in POOLS:
            out[p] = floors.get(p, 0)
        return out

    # ---- recompute -----------------------------------------------------------------
    def recompute(self, emit: bool = True) -> dict[str, Any]:
        preferred_targets = {p: self.target(p) for p in POOLS}
        target_total = self.target_total()
        preferred_low_waters = {p: self.low_water(p) for p in POOLS}
        cap = self.cap()
        max_initializing = self.max_initializing()
        threshold = self.idle_reclaim_threshold()
        pending = self.read_queue()
        pending_total = sum(pending.values())
        targets = dict(preferred_targets)
        low_waters = dict(preferred_low_waters)
        shared_total = policy_value("concurrency", "target_total", None, self.root)
        active_pools = [p for p in POOLS if pending[p] > 0]
        # 12/4 is a preference, not a partition. If only one pool has work it
        # borrows the other pool's reservation and may use the full shared 16.
        if isinstance(shared_total, int) and not isinstance(shared_total, bool):
            if len(active_pools) == 1:
                only = active_pools[0]
                targets = {p: (target_total if p == only else 0) for p in POOLS}
                shared_low = min(target_total, sum(preferred_low_waters.values()))
                low_waters = {p: (shared_low if p == only else 0) for p in POOLS}
        counts, ids = self.read_roster_state()
        initializing = {p: counts[p]["initializing"] for p in POOLS}
        running = {p: counts[p]["running"] for p in POOLS}
        idle = {p: counts[p]["idle"] for p in POOLS}
        completed = {p: counts[p]["completed"] for p in POOLS}
        shutdown_pending = {p: counts[p]["shutdown_pending"] for p in POOLS}
        reclaimable = {p: idle[p] + completed[p] + shutdown_pending[p] for p in POOLS}
        initializing_total = sum(initializing.values())
        running_total = sum(running.values())
        reclaimable_total = sum(reclaimable.values())
        occupied_total = initializing_total + running_total + reclaimable_total
        prior = self.read_state()
        throttle = read_json(self.throttle_state_path, {})
        blocked_until = float(throttle.get("blocked_until", 0) or 0)
        backoff_active = blocked_until > time.time()
        finalized = bool(prior.get("finalized"))
        queue_empty = pending_total <= 0

        # Per-pool watermarks: a pool is refill-required only when IT has
        # pending work and its own running count is below its own low water.
        required = {p: bool(not queue_empty and not finalized and
                            pending[p] > 0 and running[p] < low_waters[p])
                    for p in POOLS}
        required_any = any(required.values())
        # Debt is based on effective RUNNING agents only. Initializing births do
        # not clear debt, but they reserve spawn capacity to prevent overshoot.
        raw_debt = {p: (min(pending[p], max(0, targets[p] - running[p]))
                        if required[p] else 0)
                    for p in POOLS}
        raw_spawn = {p: max(0, raw_debt[p] - initializing[p]) for p in POOLS}
        host_capacity = max(0, cap - occupied_total)
        target_capacity = max(0, target_total - running_total - initializing_total)
        birth_capacity = max(0, max_initializing - initializing_total)
        spawn_capacity_now = min(host_capacity, target_capacity, birth_capacity)
        if backoff_active:
            spawn_capacity_now = 0
        deficit_total = min(sum(raw_spawn.values()), spawn_capacity_now) if required_any else 0
        deficit = self.split_deficit(deficit_total, raw_spawn)
        debt_total = sum(raw_debt.values()) if required_any else 0
        model_pool = sorted(p for p in POOLS
                            if raw_debt[p] > 0 or (required[p] and pending[p] > 0))

        # Reuse/assign first: idle agents in pools with pending work are
        # suggested for assignment, up to the number of pending items.
        reuse_ids = {p: (list(ids[p]["idle"][:min(len(ids[p]["idle"]),
                                                  pending[p])])
                         if required[p] else [])
                     for p in POOLS}
        reuse_total = sum(len(v) for v in reuse_ids.values())
        reuse_required = bool(required_any and reuse_total > 0)
        # Per-pool reclaim: excess idle (beyond reuse) plus completed and
        # shutdown_pending agents of pools that actually need refilling.
        excess_ids = {p: ((ids[p]["idle"][len(reuse_ids[p]):] +
                           ids[p]["completed"] + ids[p]["shutdown_pending"])
                          if required[p] else [])
                      for p in POOLS}
        excess_total = sum(len(v) for v in excess_ids.values())
        idle_reclaim_required_pool = {
            p: bool(required[p] and len(excess_ids[p]) > threshold)
            for p in POOLS}
        idle_reclaim_required = any(idle_reclaim_required_pool.values())
        host_close_agent = sorted({aid for p in POOLS
                                   if idle_reclaim_required_pool[p]
                                   for aid in excess_ids[p]})
        # Reclaim-first capacity case: slots are full but reclaimable agents hold
        # them; the scheduler is allowed (and required) to close then refill.
        reclaim_first = bool(required_any and occupied_total >= cap
                             and reclaimable_total > 0)
        if reclaim_first and not idle_reclaim_required:
            idle_reclaim_required = True
            host_close_agent = sorted({aid
                                       for pool in POOLS
                                       for aid in (ids[pool]["idle"] +
                                                   ids[pool]["completed"] +
                                                   ids[pool]["shutdown_pending"])})

        if queue_empty:
            reason = "queue_empty"
        elif finalized:
            reason = "release_finalize"
        elif required_any and backoff_active:
            reason = "spawn_backoff"
        elif required_any and deficit_total == 0 and initializing_total >= max_initializing:
            reason = "initializing_cap"
        elif required_any and deficit_total == 0 and running_total + initializing_total >= target_total:
            reason = "at_total_target"
        elif required_any and deficit_total == 0 and occupied_total >= cap:
            reason = "at_cap"
        elif required_any:
            reason = "below_low_water"
        else:
            reason = "at_or_above_low_water"
        state = {
            "schema": STATE_SCHEMA,
            "target": targets,
            "preferred_target": preferred_targets,
            "target_total": target_total,
            "configured_target_sum": sum(preferred_targets.values()),
            "low_water": low_waters,
            "preferred_low_water": preferred_low_waters,
            "low_water_total": sum(low_waters.values()),
            "cap": cap,
            "idle_reclaim_threshold": threshold,
            "max_initializing": max_initializing,
            "effective_concurrency": running_total,
            "initializing": {"total": initializing_total, **initializing},
            "active": {"total": running_total, **running},
            "idle": {"total": sum(idle.values()), **idle},
            "completed": {"total": sum(completed.values()), **completed},
            "shutdown_pending": {"total": sum(shutdown_pending.values()), **shutdown_pending},
            "occupied": {"total": occupied_total,
                         **{p: running[p] + reclaimable[p] for p in POOLS}},
            "reclaimable": {"total": reclaimable_total, **reclaimable},
            "pending": {"total": pending_total, **pending},
            "refill_required": required_any,
            "refill_required_by_pool": required,
            "reuse_required": reuse_required,
            "reuse": reuse_ids,
            "idle_reclaim_required": idle_reclaim_required,
            "idle_reclaim_required_by_pool": idle_reclaim_required_pool,
            "host_close_agent_required": idle_reclaim_required,
            "host_close_agent": host_close_agent if idle_reclaim_required else [],
            "reclaim_first": reclaim_first,
            "spawn_capacity_now": spawn_capacity_now,
            "spawn_capacity": {"host": host_capacity, "target": target_capacity,
                               "initializing": birth_capacity},
            "spawn_throttle": {
                "backoff_active": backoff_active,
                "blocked_until": blocked_until,
                "last_spawn_at": throttle.get("last_spawn_at"),
                "last_health": throttle.get("last_health"),
                "last_error": throttle.get("last_error"),
            },
            "deficit": {"total": deficit_total, **deficit},
            "model_pool": model_pool,
            "debt_held": {"total": deficit_total if required_any else 0,
                          **{p: (deficit[p] if required[p] else 0)
                             for p in POOLS}},
            "unfulfilled_demand": {"total": debt_total,
                                   **{p: (raw_debt[p] if required[p] else 0)
                                      for p in POOLS}},
            "queue_empty": queue_empty,
            "finalized": finalized,
            "reason": reason,
            "spawn_mechanism": ("host_spawn_required" if not self.host_spawn_available()
                                else "host_direct"),
            "host_spawn_available": self.host_spawn_available(),
            "refilled": False,
            "updated_at": time.time(),
        }
        if emit:
            with lock(self.lock_path):
                atomic_json(self.state_path, state)
                slim = {k: state[k] for k in
                         ("refill_required", "deficit", "model_pool", "reason",
                          "initializing", "active", "idle", "completed", "shutdown_pending",
                          "occupied", "reclaimable", "pending", "debt_held",
                          "unfulfilled_demand",
                          "reuse_required", "reuse", "idle_reclaim_required",
                          "idle_reclaim_required_by_pool", "host_close_agent",
                          "reclaim_first", "spawn_capacity_now", "spawn_throttle",
                          "refill_required_by_pool")}
                if required_any:
                    self._append_event("refill_required", slim)
                    if reuse_required:
                        self._append_event("reuse_required",
                                           {"reuse": reuse_ids, "deficit": deficit,
                                            "required_by_pool": required})
                    if idle_reclaim_required:
                        self._append_event("idle_reclaim_required",
                                           {"host_close_agent": host_close_agent,
                                            "reclaim_first": reclaim_first})
                elif prior.get("refill_required"):
                    self._append_event("refill_clear", slim)
            return state

    # ---- lifecycle commands -----------------------------------------------------------
    def release_finalize(self) -> dict[str, Any]:
        """Explicit finalization: clear refill_required and debt until resumed."""
        state = self.read_state()
        state["finalized"] = True
        atomic_json(self.state_path, state)
        return self.recompute(emit=True)

    def resume(self) -> dict[str, Any]:
        state = self.read_state()
        state["finalized"] = False
        atomic_json(self.state_path, state)
        return self.recompute(emit=True)

    def spawn_intent(self, count: int, pool: str = "v4") -> dict[str, Any]:
        """Record that the host intends to spawn; NEVER clears debt or deficit.

        Only observed running agents (native roster) reduce the deficit, so an
        intent that never materializes stays fail-visible in refill_state.
        """
        with lock(self.lock_path):
            self._append_event("spawn_intent", {"count": int(count), "pool": pool,
                                                "debt_cleared": False})
        return self.read_state()

    def _append_event(self, event: str, detail: dict[str, Any]) -> None:
        self.refill_dir.mkdir(parents=True, exist_ok=True)
        with self.events_path.open("a", encoding="utf-8", newline="\n") as handle:
            handle.write(json.dumps({"ts": time.time(), "event": event, **detail},
                                    ensure_ascii=False, separators=(",", ":")) + "\n")


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(
        description="Mechanical sustained-refill controller. Prints refill_state.json "
                    "as JSON after the requested action.")
    ap.add_argument("--root", type=Path, default=None,
                    help="LOOP root (default: $LOOP_ROOT or the package root)")
    ap.add_argument("--status", action="store_true",
                    help="print the current refill state (read-only)")
    ap.add_argument("--recompute", action="store_true",
                    help="recompute and rewrite the refill state")
    ap.add_argument("--queue-set", type=int, metavar="N",
                    help="set the work queue count for --pool")
    ap.add_argument("--queue-add", type=int, metavar="N",
                    help="add N pending work items for --pool")
    ap.add_argument("--queue-remove", type=int, metavar="N",
                    help="remove N pending work items for --pool")
    ap.add_argument("--queue-clear", action="store_true",
                    help="empty the work queue (clears refill_required)")
    ap.add_argument("--queue-sync-ledger", action="store_true",
                    help="count DISPATCHABLE packets into --pool from the progress ledger")
    ap.add_argument("--pool", choices=list(POOLS), default=None,
                    help="model pool for queue/intent commands (default: v4)")
    ap.add_argument("--spawn-intent", type=int, metavar="N",
                    help="record host spawn intent for N agents (debt is NOT cleared)")
    ap.add_argument("--release-finalize", action="store_true",
                    help="explicitly clear refill_required and debt (finalize)")
    ap.add_argument("--resume", action="store_true",
                    help="undo --release-finalize")
    args = ap.parse_args(argv)

    ctl = RefillController(args.root)
    pool = args.pool or "v4"
    mutated = False
    if args.queue_set is not None:
        ctl.queue_set(args.queue_set, pool)
        mutated = True
    if args.queue_add is not None:
        ctl.queue_add(args.queue_add, pool)
        mutated = True
    if args.queue_remove is not None:
        ctl.queue_remove(args.queue_remove, pool)
        mutated = True
    if args.queue_clear:
        ctl.queue_clear()
        mutated = True
    if args.queue_sync_ledger:
        ctl.queue_sync_ledger(pool)
        mutated = True
    if args.spawn_intent is not None:
        ctl.spawn_intent(args.spawn_intent, pool)
    if args.release_finalize:
        ctl.release_finalize()
        mutated = True
    if args.resume:
        ctl.resume()
        mutated = True

    if args.status and not mutated:
        out = ctl.read_state()
    else:
        out = ctl.recompute(emit=True)
    print(json.dumps(out, ensure_ascii=False, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Mechanical actuator for the canonical v2 refill controller.

This module is deliberately not another controller.  It synchronizes demand
from the packet ledger, asks :class:`RefillControllerV2` for the bounded
deficit, emits a packet-only manifest, and hands that manifest to the existing
``headless_wave`` transport.  It never invents work or embeds a free-form
prompt: every task must resolve to a validated ``data/packets/<id>.json`` and
is physically dispatched by ``DispatcherV2``.
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
import time
from pathlib import Path
from typing import Any, Mapping

try:
    import headless_wave
    from dispatch_v2 import validate_packet_id
    from orchestration_common import (LoopPaths, atomic_write_json, file_lock,
                                      read_json)
    from refill_controller_v2 import (K3_ROLES, K3_WORK_STATES,
                                      RefillControllerV2, pool_for_packet)
except ImportError:  # pragma: no cover - direct execution
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    import headless_wave
    from dispatch_v2 import validate_packet_id
    from orchestration_common import (LoopPaths, atomic_write_json, file_lock,
                                      read_json)
    from refill_controller_v2 import (K3_ROLES, K3_WORK_STATES,
                                      RefillControllerV2, pool_for_packet)


K3_ROLE_BY_STATE = {
    "EXPAND_K3": "plan_expander",
    "L2_VERIFY": "verifier",
    "L2_VERIFY_PENDING": "verifier",
    "L2_RANK": "verifier",
}


class RefillConsumerError(RuntimeError):
    pass


def _process_alive(pid: int) -> bool:
    try:
        if os.name == "nt":
            import ctypes
            from ctypes import wintypes
            handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, int(pid))
            if not handle:
                return False
            try:
                code = wintypes.DWORD()
                return bool(ctypes.windll.kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(code))) and code.value == 259
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        os.kill(int(pid), 0)
        return True
    except (OSError, TypeError, ValueError):
        return False


def _proc_start_ticks(pid: int) -> int | None:
    if os.name == "nt":
        try:
            import ctypes
            from ctypes import wintypes
            handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, int(pid))
            if not handle:
                return None
            try:
                creation = wintypes.FILETIME()
                exit_time = wintypes.FILETIME()
                kernel = wintypes.FILETIME()
                user = wintypes.FILETIME()
                if not ctypes.windll.kernel32.GetProcessTimes(
                        handle, ctypes.byref(creation), ctypes.byref(exit_time),
                        ctypes.byref(kernel), ctypes.byref(user)):
                    return None
                return ((int(creation.dwHighDateTime) << 32)
                        | int(creation.dwLowDateTime))
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        except (OSError, TypeError, ValueError):
            return None
    try:
        return int(Path("/proc/%d/stat" % int(pid)).read_text(
            encoding="ascii").split()[21])
    except (OSError, TypeError, ValueError, IndexError):
        return None


def _process_generation_alive(pid: int, ticks: int | None) -> bool:
    return ticks is not None and _process_alive(pid) \
        and _proc_start_ticks(pid) == int(ticks)


def schedule_run(root: Path, *, source: str) -> dict[str, Any]:
    """Coalesce and detach the packet-only refill actuator.

    Desktop lifecycle events must not invoke the full orchestration epilogue:
    that would also drain the shared audit event stream.  This runner performs
    only the existing packet-ledger refill transaction and therefore cannot
    invent work or mutate the state machine from transport-only events.
    """
    root = Path(root).resolve()
    orchestration = root / "data" / "orchestration"
    orchestration.mkdir(parents=True, exist_ok=True)
    marker = orchestration / "refill_actuator.pid"
    requests = orchestration / "refill_requests.json"
    log_path = orchestration / "refill_actuator.log"
    claim = orchestration / ".refill_actuator_schedule.lock"
    with file_lock(claim):
        request_state = read_json(requests, {"requested_seq": 0,
                                             "consumed_seq": 0}) or {}
        request_state["requested_seq"] = int(
            request_state.get("requested_seq", 0) or 0) + 1
        request_state.update(source=source, updated_at=time.time())
        atomic_write_json(requests, request_state)
        try:
            marker_value = read_json(marker, {}) or {}
            prior_pid = int(marker_value["pid"])
            prior_ticks = int(marker_value["proc_start_ticks"])
        except (KeyError, TypeError, ValueError):
            prior_pid, prior_ticks = 0, None
        if prior_pid and _process_generation_alive(prior_pid, prior_ticks):
            return {"status": "coalesced", "pid": prior_pid, "source": source}
        log = log_path.open("ab")
        kwargs: dict[str, Any] = {
            "cwd": str(root), "env": {**os.environ, "LOOP_ROOT": str(root)},
            "stdin": subprocess.DEVNULL, "stdout": log, "stderr": subprocess.STDOUT,
            "close_fds": True,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                       | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        else:
            kwargs["start_new_session"] = True
        try:
            proc = subprocess.Popen(
                [sys.executable, str(root / "harness" / "refill_consumer_v2.py"),
                 "--root", str(root), "--source", source], **kwargs)
            atomic_write_json(marker, {"pid": proc.pid,
                                       "proc_start_ticks": _proc_start_ticks(proc.pid)})
            return {"status": "scheduled", "pid": proc.pid, "source": source,
                    "log": str(log_path)}
        finally:
            log.close()


def schedule_delayed_run(root: Path, *, wake_at: float,
                         source: str) -> dict[str, Any]:
    """Schedule one detached wake after provider/transport backoff expires."""
    root = Path(root).resolve()
    orchestration = root / "data" / "orchestration"
    orchestration.mkdir(parents=True, exist_ok=True)
    marker = orchestration / "refill_backoff_wake.json"
    with file_lock(orchestration / ".refill_backoff_wake.lock"):
        old = read_json(marker, {}) or {}
        try:
            old_pid = int(old.get("pid", 0) or 0)
            old_ticks = int(old.get("proc_start_ticks"))
            old_wake = float(old.get("wake_at", 0) or 0)
        except (TypeError, ValueError):
            old_pid, old_ticks, old_wake = 0, None, 0.0
        if (old_pid and _process_generation_alive(old_pid, old_ticks)
                and old_wake <= wake_at):
            return {"status": "coalesced", "pid": old_pid,
                    "wake_at": old_wake, "source": source}
        delay = max(0.0, wake_at - time.time())
        log = (orchestration / "refill_actuator.log").open("ab")
        kwargs: dict[str, Any] = {
            "cwd": str(root), "env": {**os.environ, "LOOP_ROOT": str(root)},
            "stdin": subprocess.DEVNULL, "stdout": log,
            "stderr": subprocess.STDOUT, "close_fds": True,
        }
        if os.name == "nt":
            kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                       | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        else:
            kwargs["start_new_session"] = True
        try:
            proc = subprocess.Popen(
                [sys.executable, str(root / "harness" / "refill_consumer_v2.py"),
                 "--root", str(root), "--source", source,
                 "--delay", "%.3f" % delay], **kwargs)
            atomic_write_json(marker, {"pid": proc.pid,
                                       "proc_start_ticks": _proc_start_ticks(proc.pid),
                                       "wake_at": wake_at, "source": source})
            return {"status": "scheduled", "pid": proc.pid,
                    "wake_at": wake_at, "source": source}
        finally:
            log.close()


def schedule_retry_if_debt(root: Path, state: Mapping[str, Any],
                           *, source: str) -> dict[str, Any] | None:
    if int((state.get("deficit") or {}).get("total", 0) or 0) <= 0:
        return None
    now = time.time()
    wake_at = now + 30.0
    health_dir = Path(root) / "data" / "provider_health"
    for path in health_dir.glob("*.json") if health_dir.exists() else ():
        doc = read_json(path, {}) or {}
        try:
            until = float(doc.get("backoff_until", 0) or 0)
        except (TypeError, ValueError):
            continue
        if until > now:
            wake_at = max(wake_at, until + 1.0)
    return schedule_delayed_run(Path(root), wake_at=wake_at, source=source)


def schedule_followup_if_debt(root: Path, state: Mapping[str, Any], *,
                              failed: bool, source: str) -> dict[str, Any] | None:
    """Keep successful refill passes from decaying between lifecycle edges.

    A provider/transport failure retains the existing bounded backoff.  A
    successful pass that still observes real debt gets one coalesced one-second
    follow-up, covering a concurrent terminal edge that landed during the
    transaction without introducing a poller or a second scheduler.
    """
    if int((state.get("deficit") or {}).get("total", 0) or 0) <= 0:
        return None
    if failed:
        return schedule_retry_if_debt(root, state, source=source)
    return schedule_delayed_run(Path(root), wake_at=time.time() + 1.0,
                                source=source)


def role_for_entry(entry: Mapping[str, Any]) -> str:
    state = str(entry.get("state") or "")
    if state in K3_ROLE_BY_STATE:
        return K3_ROLE_BY_STATE[state]
    role = str(entry.get("role") or "")
    if role in {"worker", "verifier", "reviewer", "plan_expander"}:
        return role
    raise RefillConsumerError(
        "DISPATCHABLE packet lacks an explicit LOOP role; refusing inherited/default model")


def validate_packet(paths: LoopPaths, packet_id: str) -> dict[str, Any]:
    validate_packet_id(packet_id)
    packet = read_json(paths.data / "packets" / (packet_id + ".json"), None)
    if not isinstance(packet, dict) or packet.get("packet_id") != packet_id:
        raise RefillConsumerError("packet file missing or id mismatch: %s" % packet_id)
    for key in ("goal", "authorized_paths", "acceptance"):
        if key not in packet:
            raise RefillConsumerError("packet %s missing %s" % (packet_id, key))
    return packet


def select_tasks(paths: LoopPaths, state: Mapping[str, Any]) -> list[dict[str, Any]]:
    """Select real packets within global and per-parent refill debt.

    Parent-managed packets are round-robined by parent id.  A parent therefore
    cannot consume another parent's refill allowance merely because its packet
    ids sort first.  Legacy non-parent packets remain supported as one bucket.
    """
    ledger = read_json(paths.ledger, {"packets": {}}) or {"packets": {}}
    deficits = state.get("deficit") if isinstance(state, Mapping) else {}
    remaining = {pool: max(0, int((deficits or {}).get(pool, 0) or 0))
                 for pool in ("v4", "k3")}
    tasks: list[dict[str, Any]] = []
    parent_states = read_json(paths.refill_dir / "parent_sessions.json",
                              {"parents": {}}) or {"parents": {}}
    state_parents = state.get("parents", {}) if isinstance(state, Mapping) else {}
    parent_remaining: dict[str, dict[str, int]] = {}
    if isinstance(state_parents, Mapping):
        for parent_id, parent_state in state_parents.items():
            if not isinstance(parent_state, Mapping):
                continue
            spawnable = parent_state.get("spawnable", {})
            parent_remaining[str(parent_id)] = {
                pool: max(0, int((spawnable or {}).get(pool, 0) or 0))
                for pool in ("v4", "k3")
            }
    buckets: dict[str, list[tuple[str, dict[str, Any], str, str | None]]] = {}
    for packet_id in sorted((ledger.get("packets") or {}).keys()):
        entry = ledger["packets"].get(packet_id)
        if not isinstance(entry, dict):
            continue
        state_name = str(entry.get("state") or "")
        # Dedicated K3 states are demand signals consumed by L2Consumer or
        # the plan pipeline; dispatching their source packet here would create
        # a duplicate verifier/expander.  This generic actuator owns only the
        # mechanically DISPATCHABLE packet lane.
        if state_name != "DISPATCHABLE":
            continue
        if entry.get("release_review"):
            # Release reviews have a dedicated once-per-wave hard-pinned
            # dispatcher and must never be consumed as ordinary refill work.
            continue
        parent_id = entry.get("parent_session_id")
        if parent_id:
            parent = (parent_states.get("parents") or {}).get(str(parent_id))
            if not isinstance(parent, dict) or parent.get("active") is not True:
                # Imported work cannot outlive its explicitly registered
                # parent.  The deficit remains visible, but no new birth is
                # admitted after Stop/inactivation.
                continue
            if parent.get("manifest_id") != entry.get("manifest_id"):
                # Keep task selection identical to queue_sync_ledger: only the
                # active admission generation supplies demand.  None/None is
                # the sole legacy-compatible case.
                continue
            if str(parent_id) not in parent_remaining:
                # A parent task only counts after the same controller snapshot
                # has established real backlog and per-parent capacity.
                continue
        pool = pool_for_packet(entry)
        key = "parent:" + str(parent_id) if parent_id else "legacy"
        buckets.setdefault(key, []).append(
            (str(packet_id), entry, pool, str(parent_id) if parent_id else None))

    while sum(remaining.values()) > 0:
        progressed = False
        for key in sorted(buckets):
            rows = buckets[key]
            chosen = None
            for index, (_, _, pool, parent_id) in enumerate(rows):
                if remaining[pool] <= 0:
                    continue
                if (parent_id is not None and
                        parent_remaining[parent_id][pool] <= 0):
                    continue
                chosen = index
                break
            if chosen is None:
                continue
            packet_id, entry, pool, parent_id = rows.pop(chosen)
            packet = validate_packet(paths, packet_id)
            role = role_for_entry(entry)
            role_pool = "k3" if role in K3_ROLES else "v4"
            if role_pool != pool:
                raise RefillConsumerError(
                    "packet %s pool/role conflict: %s vs %s" %
                    (packet_id, pool, role))
            tasks.append({
                "task_id": packet_id,
                "task_name": str(entry.get("task_name") or packet.get("goal")
                                 or packet_id)[:160],
                "packet_id": packet_id,
                "role": role,
                **({"parent_session_id": parent_id} if parent_id else {}),
                **({"manifest_id": str(entry["manifest_id"])}
                   if entry.get("manifest_id") else {}),
            })
            remaining[pool] -= 1
            if parent_id is not None:
                parent_remaining[parent_id][pool] -= 1
            progressed = True
        if not progressed:
            break
    return tasks


def build_manifest(paths: LoopPaths, state: Mapping[str, Any]) -> Path | None:
    tasks = select_tasks(paths, state)
    if not tasks:
        return None
    path = paths.refill_dir / "packet_wave.json"
    atomic_write_json(path, {
        "schema": "codex-loop-packet-wave/v1",
        "policy_version": state.get("policy_version"),
        "deficit_snapshot": state.get("deficit"),
        "tasks": tasks,
    })
    return path


def run_once(root: Path, *, dry_run: bool = False,
             observe_timeout: float = 5.0) -> tuple[int, dict[str, Any]]:
    paths = LoopPaths.resolve(root)
    # One actuator transaction per LOOP root.  The controller has its own
    # short state lock; this separate lock spans selection through stable
    # roster observation and closes the pre-roster double-birth race.
    with file_lock(paths.refill_dir / ".consumer.lock"):
        controller = RefillControllerV2(paths)
        controller.queue_sync_ledger()
        before = controller.recompute()
        manifest = build_manifest(paths, before)
        if manifest is None:
            return 0, {"status": "idle", "state": before, "manifest": None}
        args = argparse.Namespace(
            manifest=manifest, root=paths.root, timeout=1800.0,
            observe_timeout=observe_timeout,
            spawn_interval_ms=controller.policy.spawn_interval_ms(),
            health_every=8, dry_run=dry_run,
        )
        rc = headless_wave.run(args)
        # Dispatch appends canonical ``dispatched`` events.  Consume them in
        # the same actuator transaction so a stably born packet immediately
        # leaves DISPATCHABLE; otherwise the debt remains selectable until an
        # unrelated terminal edge and the same packet can be offered again.
        try:
            from statemachine_v2 import StateMachine
            state_machine = StateMachine(paths).step()
        except Exception as exc:
            state_machine = {"status": "failed",
                             "error": "%s: %s" % (type(exc).__name__, exc)}
            rc = rc or 3
        controller.queue_sync_ledger()
        after = controller.recompute()
        retry_wake = (schedule_followup_if_debt(
            root, after, failed=bool(rc),
            source=("refill_debt_backoff" if rc else "refill_residual_debt"))
            if not dry_run else None)
        return rc, {"status": "dry_run" if dry_run else "dispatched",
                    "manifest": str(manifest), "before": before,
                    "state_machine": state_machine, "after": after,
                    "retry_wake": retry_wake}


def drain_requested(root: Path, *, source: str, dry_run: bool = False,
                    observe_timeout: float = 5.0) -> tuple[int, dict[str, Any]]:
    """Drain every durable refill edge, including edges coalesced mid-run."""
    root = Path(root).resolve()
    orchestration = root / "data" / "orchestration"
    orchestration.mkdir(parents=True, exist_ok=True)
    requests = orchestration / "refill_requests.json"
    marker = orchestration / "refill_actuator.pid"
    claim = orchestration / ".refill_actuator_schedule.lock"
    overall_rc = 0
    passes: list[dict[str, Any]] = []
    while True:
        request_state = read_json(requests, {"requested_seq": 1,
                                             "consumed_seq": 0}) or {}
        requested = int(request_state.get("requested_seq", 1) or 1)
        rc, result = run_once(root, dry_run=dry_run,
                              observe_timeout=observe_timeout)
        overall_rc = overall_rc or rc
        passes.append(result)
        with file_lock(claim):
            latest = read_json(requests, request_state) or request_state
            latest["consumed_seq"] = max(
                int(latest.get("consumed_seq", 0) or 0), requested)
            latest["consumed_at"] = time.time()
            atomic_write_json(requests, latest)
            if int(latest.get("requested_seq", 0) or 0) <= requested:
                marker_value = read_json(marker, {}) or {}
                if (isinstance(marker_value, dict)
                        and int(marker_value.get("pid", -1) or -1) == os.getpid()):
                    try:
                        marker.unlink()
                    except FileNotFoundError:
                        pass
                return overall_rc, {"status": passes[-1].get("status", "idle"),
                                    "source": source, "passes": passes,
                                    "requested_seq": requested,
                                    "consumed_seq": latest["consumed_seq"]}


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Actuate real v2 refill packets once")
    ap.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    ap.add_argument("--observe-timeout", type=float, default=5.0)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--source", default="cli")
    ap.add_argument("--delay", type=float, default=0.0)
    args = ap.parse_args(argv)
    if args.delay > 0:
        time.sleep(args.delay)
        wake_marker = (args.root / "data" / "orchestration" /
                       "refill_backoff_wake.json")
        wake = read_json(wake_marker, {}) or {}
        if isinstance(wake, dict) and int(wake.get("pid", -1) or -1) == os.getpid():
            try:
                wake_marker.unlink()
            except FileNotFoundError:
                pass
        print(json.dumps(schedule_run(args.root, source=args.source),
                         ensure_ascii=False))
        return 0
    try:
        rc, result = drain_requested(args.root, source=args.source,
                                     dry_run=args.dry_run,
                                     observe_timeout=args.observe_timeout)
    except (OSError, ValueError, RefillConsumerError) as exc:
        print(json.dumps({"status": "failed", "error": str(exc)}, ensure_ascii=False))
        return 3
    print(json.dumps({**result, "source": args.source, "ts": time.time()},
                     ensure_ascii=False))
    return rc


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""refill_controller_v2.py бк Pool-aware sustained refill (P0-6 fix, бь2.6).

Fixes the demand side of the K3 starvation:

* **``queue_sync_ledger`` is pool-aware and total.**  The shipped
  ``refill_controller.py:203-208`` counted DISPATCHABLE packets into a single
  ``--pool`` argument defaulting to ``"v4"``, so K3-pool demand was never
  written and the configured K3 reservation was permanently borrowed by V4.
  v2 derives the pool per packet from role/``pool_hint`` metadata
  (verifier/reviewer/plan_expander б· ``k3``, else ``v4``) and counts the K3
  work states (``L2_VERIFY``, ``EXPAND_K3``, ``L2_RANK``) as K3 demand.  The
  sync writes BOTH pools in one atomic mutation; the ``--pool`` flag no
  longer applies to sync (it stays for manual ``queue-add``/``remove`` ops).
* **Configured K3 target with actual demand matching:** targets/low-waters come
  fail-closed from ``refill_policy.toml`` (the only concurrency authority;
  policy unreadable => :class:`PolicyError`, never the silent divergent
  16/16-vs-48 defaults of v1).  A pool refills only when it has pending work
  AND its running count is below its low water бк demand-backed, never idle
  filling (anti-pattern canary: zero demand ? zero K3 spawns).
* **Reservations borrowable (true):** when only one pool has pending work it
  may borrow the other pool's reservation up to ``target_total``; watermark
  logic reclaims borrowed slots naturally once K3 demand exists.
* **Policy-version stamping:** ``refill_state.json`` records the policy
  version + mtime it was computed from; a mismatch on read forces a
  recompute, so a stale state file can never silently win (P0-8.3).
"""
from __future__ import annotations

import argparse
import ctypes
import json
import os
import sys
import time
import urllib.request
from ctypes import wintypes
from pathlib import Path
from typing import Any, Callable, Final, Mapping

try:
    from orchestration_common import (LoopPaths, PolicyError, RefillPolicy,
                                      append_ndjson, atomic_write_json, file_lock,
                                      get_logger, read_json, utc_now)
except ImportError:  # pragma: no cover - direct CLI execution
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from orchestration_common import (LoopPaths, PolicyError, RefillPolicy,
                                      append_ndjson, atomic_write_json, file_lock,
                                      get_logger, read_json, utc_now)

__all__ = [
    "POOLS",
    "K3_ROLES",
    "K3_WORK_STATES",
    "pool_for_packet",
    "RefillControllerV2",
    "main",
]

log = get_logger("loop.refill_controller_v2")

POOLS: Final[tuple[str, str]] = ("v4", "k3")
STATE_SCHEMA: Final[str] = "codex-loop-refill/v3"
QUEUE_SCHEMA: Final[str] = "codex-loop-refill-queue/v2"

#: Roles whose packets are K3 demand.
K3_ROLES: Final[frozenset[str]] = frozenset({"verifier", "reviewer", "plan_expander"})
#: v2 state-machine states that ARE K3 work (count as K3 demand while active).
K3_WORK_STATES: Final[frozenset[str]] = frozenset(
    {"L2_VERIFY", "L2_RANK", "EXPAND_K3", "L2_VERIFY_PENDING"})
NATIVE_RUNNING_TTL_SECONDS: Final[float] = 1800.0
OBSERVER_URL: Final[str] = "http://127.0.0.1:8765/api/status"


def _process_start_token(pid: Any) -> int | None:
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return None
    if os.name == "nt":
        handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
        if not handle:
            return None
        try:
            code = wintypes.DWORD()
            if (not ctypes.windll.kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(code)) or code.value != 259):
                return None
            creation = wintypes.FILETIME(); exit_time = wintypes.FILETIME()
            kernel = wintypes.FILETIME(); user = wintypes.FILETIME()
            if not ctypes.windll.kernel32.GetProcessTimes(
                    handle, ctypes.byref(creation), ctypes.byref(exit_time),
                    ctypes.byref(kernel), ctypes.byref(user)):
                return None
            return ((int(creation.dwHighDateTime) << 32)
                    | int(creation.dwLowDateTime))
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    try:
        return int(Path("/proc/%d/stat" % pid).read_text(
            encoding="ascii").split()[21])
    except (OSError, ValueError, IndexError):
        return None


def _process_generation_alive(pid: Any, expected: Any) -> bool:
    actual = _process_start_token(pid)
    if actual is None:
        return False
    try:
        return expected is not None and actual == int(expected)
    except (TypeError, ValueError):
        return False


def pool_for_packet(item: Mapping[str, Any]) -> str:
    """Mechanically derive the pool for a ledger packet entry.

    Priority: explicit ``pool_hint`` > role (verifier/reviewer/plan_expander
    б· k3) > default v4.  Zero-model, deterministic (бь2.6.1)."""
    hint = item.get("pool_hint")
    if isinstance(hint, str) and hint in POOLS:
        return hint
    role = str(item.get("role") or "")
    return "k3" if role in K3_ROLES else "v4"


def classify_pool(model: Any) -> str:
    """Route an *observed* agent model string into v4/k3 (accounting only)."""
    value = str(model or "").lower()
    return "k3" if ("k3" in value or "r1" in value or "reasoner" in value) else "v4"


class RefillControllerV2:
    """Mechanical, pool-aware refill state machine.

    The controller never calls the host spawn API: it publishes
    machine-readable ``refill_required`` records carrying per-pool deficits
    and keeps unfulfilled debt fail-visible (unchanged v1 contract)."""

    def __init__(self, paths: LoopPaths | None = None) -> None:
        self.paths = paths or LoopPaths.resolve()
        self.policy = RefillPolicy.load(self.paths)   # fail-closed (PolicyError)
        self.refill_dir = self.paths.refill_dir
        self.state_path = self.refill_dir / "refill_state.json"
        self.queue_path = self.refill_dir / "work_queue.json"
        self.events_path = self.refill_dir / "events.ndjson"
        self.lock_path = self.refill_dir / ".refill.lock"
        self.roster_path = self.paths.data / "lifecycle" / "native_roster.json"
        self.exec_roster_path = self.paths.data / "lifecycle" / "exec_roster.json"
        self.parent_sessions_path = self.refill_dir / "parent_sessions.json"
        self.observer_status = "unavailable"

    # ------------------------------------------------------------------ config
    def targets(self) -> dict[str, int]:
        return {"v4": self.policy.v4_target(), "k3": self.policy.k3_target()}

    def low_waters(self) -> dict[str, int]:
        return {"v4": min(self.policy.v4_target(), self.policy.v4_low_water()),
                "k3": min(self.policy.k3_target(), self.policy.k3_low_water())}

    def target_total(self) -> int:
        return self.policy.target_total()

    # ------------------------------------------------------------------ queue
    def read_queue(self) -> dict[str, int]:
        doc = read_json(self.queue_path, {}) or {}
        pools = doc.get("pools", {}) if isinstance(doc, dict) else {}
        return {p: max(0, int(pools.get(p, 0) or 0)) for p in POOLS}

    def read_parent_queue(self) -> dict[str, dict[str, Any]]:
        doc = read_json(self.queue_path, {}) or {}
        source = doc.get("parents", {}) if isinstance(doc, dict) else {}
        out: dict[str, dict[str, Any]] = {}
        source_items = source.items() if isinstance(source, dict) else ()
        for parent_id, row in source_items:
            if not isinstance(row, dict):
                continue
            pools = {p: max(0, int(row.get(p, 0) or 0)) for p in POOLS}
            out[str(parent_id)] = {
                "total": sum(pools.values()), **pools,
                "manifest_id": row.get("manifest_id"),
            }
        return out

    def _write_queue_unlocked(
            self, pools: Mapping[str, int],
            parents: Mapping[str, Mapping[str, Any]] | None = None) -> dict[str, int]:
        clean = {p: max(0, int(pools.get(p, 0) or 0)) for p in POOLS}
        if parents is None:
            parents = self.read_parent_queue()
        clean_parents: dict[str, dict[str, Any]] = {}
        for parent_id, row in parents.items():
            parent_pools = {p: max(0, int(row.get(p, 0) or 0)) for p in POOLS}
            clean_parents[str(parent_id)] = {
                "total": sum(parent_pools.values()), **parent_pools,
                "manifest_id": row.get("manifest_id"),
            }
        atomic_write_json(self.queue_path,
                          {"schema": QUEUE_SCHEMA, "pools": clean,
                           "parents": clean_parents,
                           "updated_at": utc_now()})
        return clean

    def _queue_mutate(self, fn: Callable[[dict[str, int]], None]) -> dict[str, int]:
        with file_lock(self.lock_path):
            pools = self.read_queue()
            fn(pools)
            return self._write_queue_unlocked(pools)

    def queue_set(self, count: int, pool: str) -> dict[str, int]:
        return self._queue_mutate(lambda p: p.__setitem__(pool, int(count)))

    def queue_add(self, count: int, pool: str) -> dict[str, int]:
        return self._queue_mutate(
            lambda p: p.__setitem__(pool, p.get(pool, 0) + int(count)))

    def queue_remove(self, count: int, pool: str) -> dict[str, int]:
        return self._queue_mutate(
            lambda p: p.__setitem__(pool, max(0, p.get(pool, 0) - int(count))))

    def queue_clear(self) -> dict[str, int]:
        with file_lock(self.lock_path):
            return self._write_queue_unlocked({p: 0 for p in POOLS})

    def queue_sync_ledger(self) -> dict[str, int]:
        """THE P0-6 FIX: pool-aware, total ledger sync.

        Counts every DISPATCHABLE packet into its mechanically derived pool
        and every K3 work state as K3 demand, then replaces BOTH pool counts
        atomically.  No ``--pool`` parameter: sync is total by definition.
        """
        led = read_json(self.paths.ledger, {"packets": {}}) or {"packets": {}}
        parent_doc = read_json(self.parent_sessions_path, {"parents": {}}) or {"parents": {}}
        registered = parent_doc.get("parents", {}) if isinstance(parent_doc, dict) else {}
        ready = {p: 0 for p in POOLS}
        parent_ready: dict[str, dict[str, Any]] = {}
        for pid, item in led.get("packets", {}).items():
            if not isinstance(item, dict):
                continue
            state = item.get("state")
            if state == "DISPATCHABLE":
                pool = pool_for_packet(item)
                parent_id = item.get("parent_session_id")
                if parent_id:
                    parent = registered.get(str(parent_id)) if isinstance(registered, dict) else None
                    if (not isinstance(parent, dict) or parent.get("active") is not True
                            or parent.get("manifest_id") != item.get("manifest_id")):
                        # Parent demand is manifest-scoped.  Equality is
                        # intentionally strict: legacy None/None remains valid,
                        # while a one-sided missing id cannot claim work from a
                        # different admission generation.
                        continue
                    row = parent_ready.setdefault(str(parent_id), {
                        "v4": 0, "k3": 0,
                        "manifest_id": item.get("manifest_id"),
                    })
                    row[pool] += 1
                ready[pool] += 1
            elif state in K3_WORK_STATES:
                ready["k3"] += 1
        with file_lock(self.lock_path):
            result = self._write_queue_unlocked(ready, parent_ready)
        log.info("queue_sync_ledger: %s", result)
        return result

    # ------------------------------------------------------------------ observed state
    def _read_roster_state(self) -> tuple[dict[str, dict[str, int]],
                                          dict[str, dict[str, int]]]:
        """Running/initializing per pool from native + exec rosters.
        Only ``running`` counts as effective concurrency (v1 contract)."""
        keys = ("initializing", "running", "idle", "completed", "shutdown_pending")
        counts = {p: {k: 0 for k in keys} for p in POOLS}
        parents: dict[str, dict[str, int]] = {}

        def remember_parent(item: Mapping[str, Any], pool: str, key: str) -> None:
            parent_id = item.get("parent_session_id")
            if not parent_id or key not in {"running", "initializing"}:
                return
            row = parents.setdefault(str(parent_id), {
                "running": 0, "initializing": 0,
                "v4_running": 0, "k3_running": 0,
                "v4_initializing": 0, "k3_initializing": 0,
            })
            row[key] += 1
            row[f"{pool}_{key}"] += 1

        now = time.time()
        roster = read_json(self.roster_path, {"agents": {}}) or {"agents": {}}
        for item in (roster.get("agents") or {}).values():
            if not isinstance(item, dict):
                continue
            role = str(item.get("agent_role") or item.get("role") or "")
            pool = ("k3" if role in K3_ROLES else "v4") if role else classify_pool(item.get("model"))
            status = str(item.get("status") or "")
            if status == "running":
                try:
                    observed_at = float(item.get("updated_at") or
                                        item.get("started_at") or 0)
                except (TypeError, ValueError):
                    observed_at = 0.0
                if observed_at <= 0 or now - observed_at > NATIVE_RUNNING_TTL_SECONDS:
                    continue
            if status in counts[pool]:
                counts[pool][status] += 1
                remember_parent(item, pool, status)
        for item in (roster.get("pending") or []):
            if not isinstance(item, dict) or item.get("status") != "pending_start":
                continue
            role = str(item.get("agent_role") or "")
            pool = ("k3" if role in K3_ROLES else "v4") if role else classify_pool(item.get("model"))
            counts[pool]["initializing"] += 1
            remember_parent(item, pool, "initializing")
        exec_roster = read_json(self.exec_roster_path, {"jobs": {}}) or {"jobs": {}}
        for item in (exec_roster.get("jobs") or {}).values():
            if not isinstance(item, dict):
                continue
            state = str(item.get("state") or "")
            key = ("initializing" if state == "starting"
                   else "running" if state == "running" else None)
            if key is None:
                continue
            supervisor_alive = _process_generation_alive(
                item.get("supervisor_pid"), item.get("supervisor_proc_start_ticks"))
            worker_alive = _process_generation_alive(
                item.get("os_pid"), item.get("worker_proc_start_ticks"))
            if not supervisor_alive or (key == "running" and not worker_alive):
                continue
            role = str(item.get("role") or item.get("agent_role") or "")
            pool = ("k3" if role in K3_ROLES else "v4") if role else classify_pool(item.get("model"))
            counts[pool][key] += 1
            remember_parent(item, pool, key)
        # The 8765 observer is the existing cross-plane aggregator.  Current
        # Desktop tasks can predate the lifecycle hook loaded by this root, so
        # native_roster alone may undercount them; WSL and Windows rosters are
        # also physically separate.  Overlay (never add) a fresh snapshot for
        # this exact LOOP root so an imported parent backlog cannot overfill by
        # mistaking already-running Desktop/peer-plane work for free slots.
        observer = self._read_observer_snapshot()
        if observer is not None:
            observed_pools = observer.get("pools", {})
            for pool in POOLS:
                # A fresh observer is the cross-plane authority.  Taking max
                # with a local stale native row could resurrect a crashed
                # Desktop child and suppress real refill debt.
                counts[pool]["running"] = max(
                    0, int((observed_pools or {}).get(pool, 0) or 0))
            for parent_id, observed in (observer.get("parents", {}) or {}).items():
                if not isinstance(observed, dict):
                    continue
                row = parents.setdefault(str(parent_id), {
                    "running": 0, "initializing": 0,
                    "v4_running": 0, "k3_running": 0,
                    "v4_initializing": 0, "k3_initializing": 0,
                })
                row["running"] = max(0, int(observed.get("running", 0) or 0))
                for pool in POOLS:
                    row[f"{pool}_running"] = max(0, int(observed.get(pool, 0) or 0))
        return counts, parents

    def _read_observer_snapshot(self) -> dict[str, Any] | None:
        self.observer_status = "unavailable"
        try:
            with urllib.request.urlopen(OBSERVER_URL, timeout=0.35) as response:
                doc = json.loads(response.read(1024 * 1024).decode("utf-8"))
        except (OSError, ValueError, TimeoutError):
            return None
        if not isinstance(doc, dict) or doc.get("freshness") not in {
                "LIVE", "QUIET", "ESTIMATED"}:
            self.observer_status = "stale"
            return None
        try:
            if time.time() - float(doc.get("timestamp", 0) or 0) > 5.0:
                return None
        except (TypeError, ValueError):
            self.observer_status = "stale"
            return None
        local = str(self.paths.root.resolve()).replace("\\", "/").casefold()
        advertised = {
            str(doc.get(key) or "").replace("\\", "/").casefold()
            for key in ("root", "windows_root")
        }
        same_package_wsl = (os.name != "nt" and local.endswith("/codex-loop-s-f2")
                            and any(path.endswith("/codex-loop-s-f2")
                                    for path in advertised))
        if local not in advertised and not same_package_wsl:
            self.observer_status = "foreign_root"
            return None
        self.observer_status = "fresh"
        return doc

    def read_roster_counts(self) -> dict[str, dict[str, int]]:
        return self._read_roster_state()[0]

    # ------------------------------------------------------------------ recompute
    def recompute(self, emit: bool = True) -> dict[str, Any]:
        """Recompute the refill state with borrowable reservations.

        Demand matching: a pool is refill-required only when IT has pending
        work and its own running count is below its own low water.  With
        ``reservations_borrowable=true`` and only one active pool, that pool
        may use the full ``target_total``; as soon as the other pool gains
        pending work its preferred reservation is honoured again (watermark
        reclaim; бь2.6.3)."""
        preferred_targets = self.targets()
        preferred_low_waters = self.low_waters()
        target_total = self.target_total()
        borrowable = self.policy.reservations_borrowable()
        pending = self.read_queue()
        pending_total = sum(pending.values())
        targets = dict(preferred_targets)
        low_waters = dict(preferred_low_waters)
        active_pools = [p for p in POOLS if pending[p] > 0]
        if borrowable and len(active_pools) == 1:
            only = active_pools[0]
            targets = {p: (target_total if p == only else 0) for p in POOLS}
            shared_low = min(target_total, sum(preferred_low_waters.values()))
            low_waters = {p: (shared_low if p == only else 0) for p in POOLS}

        counts, parent_counts = self._read_roster_state()
        running = {p: counts[p]["running"] for p in POOLS}
        initializing = {p: counts[p]["initializing"] for p in POOLS}
        running_total = sum(running.values())
        initializing_total = sum(initializing.values())
        prior = read_json(self.state_path, {}) or {}
        finalized = bool(prior.get("finalized"))
        queue_empty = pending_total <= 0

        # Parent targets are dialogue-level, not a second reservation for one
        # model family. If a parent still has real K3 work while the preferred
        # K3 pool is full but global capacity is available in V4, its debt must
        # borrow that idle family capacity or the parent can be stuck at 18/20
        # with parent deficit > 0 but global k3 deficit == 0.
        parent_registry_doc = read_json(
            self.parent_sessions_path, {"parents": {}}) or {"parents": {}}
        parent_registry = (parent_registry_doc.get("parents", {})
                           if isinstance(parent_registry_doc, dict) else {})
        parent_pending = self.read_parent_queue()
        dialogue_limit = (self.policy.dialogue_target()
                          if isinstance(parent_registry, dict) and parent_registry else 0)
        parent_demand = {p: 0 for p in POOLS}
        for parent_id, registered in (
                parent_registry.items() if isinstance(parent_registry, dict) else ()):
            if not isinstance(registered, dict) or registered.get("active") is not True:
                continue
            try:
                parent_target = int(registered.get("target_active") or dialogue_limit)
            except (TypeError, ValueError):
                parent_target = dialogue_limit
            parent_target = max(1, min(dialogue_limit, parent_target))
            observed = parent_counts.get(str(parent_id), {})
            parent_running = max(0, int(observed.get("running", 0) or 0))
            queued = parent_pending.get(str(parent_id), {})
            queued_pools = {p: max(0, int(queued.get(p, 0) or 0)) for p in POOLS}
            parent_debt = min(sum(queued_pools.values()),
                              max(0, parent_target - parent_running))
            split = self._split_deficit(parent_debt, queued_pools)
            for pool in POOLS:
                parent_demand[pool] += split[pool]

        # Sustained refill means demand-backed slots are restored to target,
        # not left parked at the low-water trigger.  Low water remains an
        # urgency/hysteresis signal exposed in state; the debt target is the
        # declared policy capacity (currently 80/60/20).
        required = {p: bool(not queue_empty and not finalized and pending[p] > 0
                            and (running[p] < targets[p] or parent_demand[p] > 0))
                    for p in POOLS}
        required_any = any(required.values())
        # Debt = min(pending, target ? running); initializing births reserve
        # capacity but never clear debt (fail-visible until observed running).
        raw_debt = {p: (max(min(pending[p], max(0, targets[p] - running[p])),
                           parent_demand[p]) if required[p] else 0)
                    for p in POOLS}
        raw_spawn = {p: max(0, raw_debt[p] - initializing[p]) for p in POOLS}
        capacity = max(0, target_total - running_total - initializing_total)
        deficit_total = min(sum(raw_spawn.values()), capacity) if required_any else 0
        deficit = self._split_deficit(deficit_total, raw_spawn)

        parent_states: dict[str, dict[str, Any]] = {}
        for parent_id, registered in sorted(
                parent_registry.items() if isinstance(parent_registry, dict) else ()):
            if not isinstance(registered, dict):
                continue
            active = registered.get("active") is True
            try:
                parent_target = int(registered.get("target_active") or dialogue_limit)
            except (TypeError, ValueError):
                parent_target = dialogue_limit
            parent_target = max(1, min(dialogue_limit, parent_target))
            observed = parent_counts.get(str(parent_id), {})
            parent_running = max(0, int(observed.get("running", 0) or 0))
            parent_initializing = max(0, int(observed.get("initializing", 0) or 0))
            queued = parent_pending.get(str(parent_id), {"total": 0, "v4": 0, "k3": 0})
            queued_pools = {p: max(0, int(queued.get(p, 0) or 0)) for p in POOLS}
            queued_total = sum(queued_pools.values())
            parent_debt = (min(queued_total, max(0, parent_target - parent_running))
                           if active else 0)
            # Starting generations reserve a birth slot but do not clear the
            # visible debt. Only a process-generation-verified running row
            # reduces ``deficit``.
            parent_spawn_total = min(
                parent_debt,
                max(0, parent_target - parent_running - parent_initializing),
                capacity,
            )
            parent_spawn = self._split_deficit(parent_spawn_total, queued_pools)
            if not active:
                parent_reason = "parent_inactive"
            elif parent_running >= parent_target:
                parent_reason = "at_parent_target"
            elif queued_total <= 0:
                parent_reason = "parent_backlog_empty"
            elif parent_spawn_total <= 0 and parent_initializing:
                parent_reason = "parent_initializing"
            elif capacity <= 0:
                parent_reason = "global_at_capacity"
            else:
                parent_reason = "below_parent_target"
            parent_states[str(parent_id)] = {
                "active": active,
                "target": parent_target,
                "running": parent_running,
                "initializing": parent_initializing,
                "pending": {"total": queued_total, **queued_pools},
                "deficit": parent_debt,
                "spawnable": {"total": parent_spawn_total, **parent_spawn},
                "reason": parent_reason,
                "manifest_id": registered.get("manifest_id"),
            }

        if queue_empty:
            reason = "queue_empty"
        elif finalized:
            reason = "release_finalize"
        elif required_any and deficit_total == 0:
            reason = "at_capacity"
        elif required_any:
            reason = ("below_low_water" if any(
                required[p] and running[p] < low_waters[p] for p in POOLS)
                else "below_target")
        else:
            reason = "at_or_above_low_water"

        state: dict[str, Any] = {
            "schema": STATE_SCHEMA,
            "policy_version": self.policy.policy_version(),
            "policy_mtime": self._policy_mtime(),
            "target": targets,
            "preferred_target": preferred_targets,
            "target_total": target_total,
            "low_water": low_waters,
            "preferred_low_water": preferred_low_waters,
            "reservations_borrowable": borrowable,
            "pending": {"total": pending_total, **pending},
            "active": {"total": running_total, **running},
            "initializing": {"total": initializing_total, **initializing},
            "refill_required": required_any,
            "refill_required_by_pool": required,
            "deficit": {"total": deficit_total, **deficit},
            "unfulfilled_demand": {"total": sum(raw_debt.values()), **raw_debt},
            "parents": parent_states,
            "cross_plane_observer": self.observer_status,
            "model_pool": sorted(p for p in POOLS if raw_debt[p] > 0),
            "queue_empty": queue_empty,
            "finalized": finalized,
            "reason": reason,
            "refilled": False,
            "updated_at": utc_now(),
        }
        if emit:
            with file_lock(self.lock_path):
                atomic_write_json(self.state_path, state)
            if required_any:
                self._append_event("refill_required",
                                   {"deficit": deficit,
                                    "model_pool": state["model_pool"],
                                    "pending": pending, "running": running})
            elif prior.get("refill_required"):
                self._append_event("refill_clear", {"pending": pending})
        return state

    @staticmethod
    def _split_deficit(total: int, pending: Mapping[str, int]) -> dict[str, int]:
        """Hamilton (largest remainder) split across pools (v1 algorithm)."""
        out = {p: 0 for p in POOLS}
        pools = [p for p in POOLS if pending.get(p, 0) > 0]
        if total <= 0 or not pools:
            return out
        grand = sum(pending[p] for p in pools)
        floors = {p: total * pending[p] // grand for p in pools}
        remainders = {p: total * pending[p] % grand for p in pools}
        remaining = total - sum(floors.values())
        for p in sorted(pools, key=lambda q: remainders[q], reverse=True):
            if remaining <= 0:
                break
            if floors[p] < pending[p]:
                floors[p] += 1
                remaining -= 1
        for p in pools:
            out[p] = min(floors[p], pending[p])
        return out

    # ------------------------------------------------------------------ state guards
    def read_state(self) -> dict[str, Any]:
        """Read the persisted state; a policy version/mtime mismatch forces a
        recompute so stale numbers can never silently win (P0-8.3)."""
        state = read_json(self.state_path, None)
        if not isinstance(state, dict):
            return self.recompute(emit=True)
        if (state.get("policy_version") != self.policy.policy_version()
                or state.get("policy_mtime") != self._policy_mtime()):
            log.warning("refill state computed from stale policy "
                        "(version %r vs %r) бк recomputing",
                        state.get("policy_version"),
                        self.policy.policy_version())
            return self.recompute(emit=True)
        return state

    def _policy_mtime(self) -> float | None:
        try:
            return self.policy.path.stat().st_mtime if self.policy.path else None
        except OSError:
            return None

    # ------------------------------------------------------------------ lifecycle
    def release_finalize(self) -> dict[str, Any]:
        state = read_json(self.state_path, {}) or {}
        state["finalized"] = True
        atomic_write_json(self.state_path, state)
        return self.recompute(emit=True)

    def resume(self) -> dict[str, Any]:
        state = read_json(self.state_path, {}) or {}
        state["finalized"] = False
        atomic_write_json(self.state_path, state)
        return self.recompute(emit=True)

    def _append_event(self, event: str, detail: Mapping[str, Any]) -> None:
        append_ndjson(self.events_path,
                      {"ts": utc_now(), "event": event, **detail})


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(
        description="Pool-aware sustained-refill controller v2. "
                    "Prints refill_state.json after the requested action.")
    ap.add_argument("--root", type=Path, default=None)
    ap.add_argument("--status", action="store_true")
    ap.add_argument("--recompute", action="store_true")
    ap.add_argument("--queue-set", type=int, metavar="N")
    ap.add_argument("--queue-add", type=int, metavar="N")
    ap.add_argument("--queue-remove", type=int, metavar="N")
    ap.add_argument("--queue-clear", action="store_true")
    ap.add_argument("--queue-sync-ledger", action="store_true",
                    help="pool-aware TOTAL sync from the progress ledger "
                         "(--pool does not apply; sync writes both pools)")
    ap.add_argument("--pool", choices=list(POOLS), default="v4",
                    help="pool for manual queue-set/add/remove ops only")
    ap.add_argument("--release-finalize", action="store_true")
    ap.add_argument("--resume", action="store_true")
    args = ap.parse_args(argv)
    try:
        ctl = RefillControllerV2(LoopPaths.resolve(args.root))
    except PolicyError as exc:
        # Fail closed AND visible: emit the error event, exit non-zero.
        print(json.dumps({"error": str(exc), "fail_closed": True}),
              file=sys.stderr)
        return 1
    mutated = False
    if args.queue_set is not None:
        ctl.queue_set(args.queue_set, args.pool); mutated = True
    if args.queue_add is not None:
        ctl.queue_add(args.queue_add, args.pool); mutated = True
    if args.queue_remove is not None:
        ctl.queue_remove(args.queue_remove, args.pool); mutated = True
    if args.queue_clear:
        ctl.queue_clear(); mutated = True
    if args.queue_sync_ledger:
        ctl.queue_sync_ledger(); mutated = True
    if args.release_finalize:
        ctl.release_finalize(); mutated = True
    if args.resume:
        ctl.resume(); mutated = True
    out = ctl.read_state() if (args.status and not mutated) \
        else ctl.recompute(emit=True)
    print(json.dumps(out, ensure_ascii=False, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Launch a visible, lifecycle-supervised headless Codex wave.

This is the low-friction transport used when Desktop should remain a light
control plane.  It does not claim a birth from ``Popen`` alone: every task is
counted only after ``lifecycle_supervisor.py`` has published the matching
run-id as ``starting`` or ``running`` in ``exec_roster.json``.  The 8765
dashboard merges that roster with its WSL peer.

The input manifest is a JSON object with ``tasks``.  Each task needs
``task_id``, ``task_name``, ``prompt`` and ``cwd``; ``role`` defaults to
``worker``.  Concurrent workspace writes require explicitly distinct working
directories and ``allow_write=true``.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import time
import urllib.request
import uuid
from dataclasses import replace
from pathlib import Path
from typing import Any

try:
    from dispatch_v2 import (DispatcherV2, ExecutionPlane, ipybox_enabled_for,
                             resolve_role_pin)
    from lifecycle_supervisor import Store
    from orchestration_common import LoopPaths, OrchestrationPolicy, read_json
except ImportError:  # pragma: no cover
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from dispatch_v2 import (DispatcherV2, ExecutionPlane, ipybox_enabled_for,
                             resolve_role_pin)
    from lifecycle_supervisor import Store
    from orchestration_common import LoopPaths, OrchestrationPolicy, read_json


TASK_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,95}\Z")
ACTIVE = {"starting", "running"}
TERMINAL = {"completed", "failed", "timed_out", "cancelled", "spawn_failed", "lost"}
ROLE_SET = {"worker", "verifier", "reviewer", "plan_expander", "duty_officer"}


class WaveError(RuntimeError):
    pass


def load_manifest(path: Path) -> list[dict[str, Any]]:
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise WaveError(f"manifest unreadable: {exc}") from exc
    tasks = doc.get("tasks") if isinstance(doc, dict) else None
    if not isinstance(tasks, list) or not tasks:
        raise WaveError("manifest.tasks must be a non-empty list")
    seen: set[str] = set()
    write_cwds: set[str] = set()
    for index, task in enumerate(tasks):
        if not isinstance(task, dict):
            raise WaveError(f"task {index} is not an object")
        task_id = str(task.get("task_id") or "")
        if not TASK_ID.fullmatch(task_id) or task_id in seen:
            raise WaveError(f"invalid or duplicate task_id {task_id!r}")
        seen.add(task_id)
        packet_id = task.get("packet_id")
        if packet_id is not None:
            if not isinstance(packet_id, str) or not TASK_ID.fullmatch(packet_id):
                raise WaveError(f"task {task_id}: invalid packet_id")
            required = ("task_name",)
        else:
            required = ("task_name", "prompt", "cwd")
        for key in required:
            if not isinstance(task.get(key), str) or not task[key].strip():
                raise WaveError(f"task {task_id}: missing {key}")
        role = str(task.get("role") or "worker")
        if role not in ROLE_SET:
            raise WaveError(f"task {task_id}: unsupported role {role!r}")
        sandbox = str(task.get("sandbox") or "read-only")
        if sandbox not in {"read-only", "workspace-write"}:
            raise WaveError(f"task {task_id}: unsupported sandbox {sandbox!r}")
        if packet_id is not None and any(
                key in task for key in ("prompt", "cwd", "sandbox", "allow_write")):
            raise WaveError(f"task {task_id}: packet tasks may not override execution details")
        if sandbox == "workspace-write":
            if task.get("allow_write") is not True:
                raise WaveError(f"task {task_id}: workspace-write needs allow_write=true")
            cwd = str(Path(task["cwd"]).resolve()).casefold()
            if cwd in write_cwds:
                raise WaveError("workspace-write tasks must use distinct cwd values")
            write_cwds.add(cwd)
    return tasks


def roster_item(data_dir: Path, packet_id: str) -> dict[str, Any]:
    doc = read_json(data_dir / "lifecycle" / "exec_roster.json", {}) or {}
    row = (doc.get("jobs") or {}).get(packet_id)
    return row if isinstance(row, dict) else {}


def process_start_token(pid: Any) -> int | None:
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return None
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes
        handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
        if not handle:
            return None
        try:
            code = wintypes.DWORD()
            if (not ctypes.windll.kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(code)) or code.value != 259):
                return None
            creation = wintypes.FILETIME(); exit_time = wintypes.FILETIME()
            kernel = wintypes.FILETIME(); user = wintypes.FILETIME()
            if not ctypes.windll.kernel32.GetProcessTimes(
                    handle, ctypes.byref(creation), ctypes.byref(exit_time),
                    ctypes.byref(kernel), ctypes.byref(user)):
                return None
            return ((int(creation.dwHighDateTime) << 32)
                    | int(creation.dwLowDateTime))
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    try:
        return int(Path("/proc/%d/stat" % pid).read_text(
            encoding="ascii").split()[21])
    except (OSError, ValueError, IndexError):
        return None


def process_alive(pid: Any, expected_start: Any = None) -> bool:
    actual = process_start_token(pid)
    if actual is None:
        return False
    if expected_start is None:
        return True
    try:
        return actual == int(expected_start)
    except (TypeError, ValueError):
        return False


def recover_live_supervisor(data_dir: Path, packet_id: str) -> dict[str, Any]:
    row = roster_item(data_dir, packet_id)
    published = row.get("published_report")
    if (row.get("state") == "lost" and row.get("exit_code") == 0
            and isinstance(published, str) and Path(published).is_file()):
        return Store(data_dir).update(
            packet_id, run_id=str(row.get("run_id") or ""),
            attempt=int(row.get("attempt", 0) or 0), state="completed",
            recovered_by="headless_wave_completed_report")
    if (row.get("state") not in ACTIVE and row.get("run_id")
            and process_alive(row.get("supervisor_pid"),
                              row.get("supervisor_proc_start_ticks"))
            and process_alive(row.get("os_pid"),
                              row.get("worker_proc_start_ticks"))):
        return Store(data_dir).update(
            packet_id, run_id=str(row["run_id"]),
            attempt=int(row.get("attempt", 0) or 0), state="running",
            heartbeat_at=time.time(), recovered_by="headless_wave")
    return row


def observed(data_dir: Path, packet_id: str, run_id: str) -> bool:
    row = roster_item(data_dir, packet_id)
    # Only RUNNING is effective concurrency.  ``starting`` merely reserves an
    # initializing slot and may be followed by spawn_failed milliseconds later.
    return row.get("run_id") == run_id and row.get("state") == "running"


def wait_observed(data_dir: Path, packet_id: str, run_id: str,
                  timeout: float = 5.0, stable_for: float = 0.25) -> bool:
    deadline = time.monotonic() + timeout
    first_running: float | None = None
    while time.monotonic() < deadline:
        row = roster_item(data_dir, packet_id)
        if row.get("run_id") != run_id:
            first_running = None
        elif row.get("state") == "running":
            first_running = first_running or time.monotonic()
            if time.monotonic() - first_running >= stable_for:
                return True
        else:
            first_running = None
            if row.get("state") in {"completed", "failed", "timed_out", "cancelled",
                                    "spawn_failed"}:
                return False
        time.sleep(0.05)
    return False


def wait_generation_change(data_dir: Path, packet_id: str, prior_run_id: str,
                           timeout: float = 5.0) -> dict[str, Any]:
    """Wait until the packet-keyed roster is overwritten by the new birth."""
    deadline = time.monotonic() + timeout
    latest: dict[str, Any] = {}
    while time.monotonic() < deadline:
        latest = roster_item(data_dir, packet_id)
        run_id = str(latest.get("run_id") or "")
        if run_id and run_id != prior_run_id:
            return latest
        time.sleep(0.05)
    return latest


def _completion_fields(row: dict[str, Any]) -> dict[str, Any]:
    """Project terminal lifecycle data into a bounded parent-facing result.

    The full report remains on disk.  Returning only its path and a bounded
    first line preserves the Fable return convention without injecting a
    completed wave's full context into the parent Desktop turn.
    """
    report = row.get("published_report") or row.get("report")
    result: dict[str, Any] = {}
    if isinstance(report, str) and report:
        result["report_path"] = report
        try:
            text = Path(report).read_text(encoding="utf-8", errors="replace")
            lines = [line.strip() for line in text.splitlines() if line.strip()]
            if lines:
                result["summary"] = lines[0][:500]
        except OSError:
            pass
    if row.get("failure") is not None:
        result["failure"] = row.get("failure")
    return result


def wait_for_terminal(data_dir: Path, results: list[dict[str, Any]],
                      timeout: float) -> None:
    """Block the parent wave until its observed generations are terminal.

    This is deliberately a deterministic supervisor wait, not an LLM/Sol
    polling round.  Parent-bound waves use it by default so the calling
    Desktop turn remains open long enough to receive child reports.  A caller
    that intentionally wants detached background work must pass ``--detach``.
    """
    pending = {
        index for index, result in enumerate(results)
        if result.get("status") in {"running", "already_active"}
        and result.get("packet_id") and result.get("run_id")
    }
    if not pending:
        return
    deadline = time.monotonic() + max(0.0, float(timeout))
    while pending:
        progressed = False
        for index in tuple(pending):
            result = results[index]
            row = recover_live_supervisor(data_dir, str(result["packet_id"]))
            expected_run = result.get("run_id")
            evidence = row if row.get("run_id") == expected_run else {}
            if not evidence:
                # A newer generation may already own the packet-keyed live
                # row.  Terminal history is keyed by immutable run_id and is
                # therefore the authoritative ABA-safe completion source.
                for history_row in reversed(row.get("history") or []):
                    if (isinstance(history_row, dict)
                            and history_row.get("run_id") == expected_run
                            and history_row.get("state") in TERMINAL):
                        evidence = history_row
                        break
            state = str(evidence.get("state") or "")
            if state not in TERMINAL:
                continue
            result["status"] = state
            result.update(_completion_fields(evidence))
            pending.remove(index)
            progressed = True
        if not pending:
            return
        if time.monotonic() >= deadline:
            for index in pending:
                results[index]["status"] = "wait_timeout"
                results[index]["failure"] = {
                    "reason": "parent_wave_wait_timeout",
                    "timeout_seconds": timeout,
                }
            return
        if not progressed:
            time.sleep(0.20)


def resolve_codex_binary() -> str:
    explicit = os.environ.get("CODEX_HEADLESS_BIN")
    if explicit:
        path = Path(explicit).resolve()
        if path.is_file():
            return str(path)
        raise WaveError(f"CODEX_HEADLESS_BIN is not a file: {path}")
    if os.name == "nt":
        npm_vendor = (Path.home() / "AppData" / "Roaming" / "npm" / "node_modules"
                      / "@openai" / "codex" / "node_modules" / "@openai"
                      / "codex-win32-x64" / "vendor" / "x86_64-pc-windows-msvc"
                      / "bin" / "codex.exe")
        if npm_vendor.is_file():
            return str(npm_vendor)
        candidate = shutil.which("codex.exe")
    else:
        candidate = shutil.which("codex")
    if not candidate:
        raise WaveError("headless codex executable not found")
    return candidate


def opencodex_healthy() -> bool:
    try:
        with urllib.request.urlopen("http://127.0.0.1:10100/healthz", timeout=2.0) as response:
            value = json.loads(response.read(65536).decode("utf-8"))
        return response.status == 200 and value.get("status") == "ok"
    except Exception:
        return False


def provider_birth_allowed(root: Path, model: str) -> bool:
    from provider_health import backoff_active
    blocked, _ = backoff_active(root, model)
    return not blocked


def launch_supervisor(command: list[str], root: Path, log_path: Path) -> int:
    log_path.parent.mkdir(parents=True, exist_ok=True)
    log = log_path.open("ab")
    kwargs: dict[str, Any] = {
        "cwd": str(root), "stdin": subprocess.DEVNULL,
        "stdout": log, "stderr": subprocess.STDOUT, "close_fds": True,
    }
    if os.name == "nt":
        kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                   | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
    else:
        kwargs["start_new_session"] = True
    try:
        proc = subprocess.Popen(command, **kwargs)
        return proc.pid
    finally:
        log.close()


def task_key(manifest: Path, task_id: str) -> str:
    digest = hashlib.sha256(str(manifest.resolve()).encode("utf-8")).hexdigest()[:10]
    return f"adhoc-{digest}-{task_id}"[:96]


def execution_pool_model(policy: OrchestrationPolicy, role: str,
                         slot: int | None) -> str | None:
    """Model for the Nth (1-based) headless worker slot from the optional
    ``[models].execution_model_pool``.

    Returns ``None`` whenever the pool does not apply (missing or empty
    pool, no slot, or a non-worker role) so callers keep the base role pin.
    """
    if slot is None or role != "worker":
        return None
    pool = policy.execution_model_pool()
    if not pool:
        return None
    return pool[(slot - 1) % len(pool)]


def build_commands(task: dict[str, Any], manifest: Path, paths: LoopPaths,
                   policy: OrchestrationPolicy, timeout: float,
                   slot: int | None = None) -> tuple[str, str, list[str], list[str], Path]:
    role = str(task.get("role") or "worker")
    pin = resolve_role_pin(role, paths, policy)
    pooled = execution_pool_model(policy, role, slot)
    if pooled is not None:
        pin = replace(pin, model=pooled)
    sandbox = str(task.get("sandbox") or "read-only")
    packet_id = task_key(manifest, str(task["task_id"]))
    run_id = f"{packet_id}-{uuid.uuid4().hex}"
    report_dir = paths.data / "reports" / "headless-wave" / packet_id / run_id
    report = report_dir / "last_message.txt"
    events = report_dir / "events.jsonl"
    stderr = report_dir / "stderr.log"
    ipybox = ipybox_enabled_for(role, ExecutionPlane.WSL_HEADLESS, policy, task)
    prompt = (
        "You are a leaf LOOP agent. Do not spawn, delegate to, create, or "
        "message any subagent/thread, and do not call multi-agent tools. "
        "Complete this bounded packet yourself and return directly to the "
        "orchestrator.\n" + str(task["prompt"])
    )
    if not prompt.lstrip().startswith("任务名："):
        prompt = f"任务名：{task['task_name']}\n{prompt}"
    worker = [resolve_codex_binary(), "exec", "--skip-git-repo-check", "--sandbox", sandbox,
              *pin.cli_overrides(), "-c",
              f"mcp_servers.ipybox.enabled={'true' if ipybox else 'false'}"]
    # The Desktop Windows config contains a complete node_repl transport and
    # needs an explicit headless disable.  WSL has no node_repl table; adding
    # only `enabled=false` would create an invalid transport at config-parse
    # time, so absence already is the desired disabled state.
    if os.name == "nt":
        worker += ["-c", "mcp_servers.node_repl.enabled=false"]
    # Headless source/audit packets do not need the Desktop Apps/plugin plane.
    # Disabling it avoids remote plugin/MCP authentication retries on every
    # birth. A bounded manifest may opt in for a task that genuinely needs it.
    if task.get("enable_apps") is not True:
        worker += ["-c", "features.apps=false",
                   "-c", "features.plugins=false",
                   "-c", "features.recommended_plugins=false",
                   "-c", "features.remote_plugin=false"]
    worker += ["--json", "-o", str(report), prompt]
    supervisor = [sys.executable, str(paths.root / "harness" / "lifecycle_supervisor.py"),
                  "--data-dir", str(paths.data), "--packet", packet_id,
                  "--run-id", run_id, "--attempt", "0",
                  *(["--parent-session-id", str(task["parent_session_id"])]
                    if task.get("parent_session_id") else []),
                  *(["--manifest-id", str(task["manifest_id"])]
                    if task.get("manifest_id") else []),
                  "--task-name", str(task["task_name"])[:160], "--role", role,
                  "--model", pin.model, "--plane",
                  "Windows CLI" if os.name == "nt" else "WSL CLI",
                  "--cwd", str(Path(task["cwd"]).resolve()),
                  "--stdout", str(events), "--stderr", str(stderr),
                  "--report", str(report), "--timeout", str(timeout), "--", *worker]
    return packet_id, run_id, supervisor, worker, report_dir


def run(args: argparse.Namespace) -> int:
    manifest = args.manifest.resolve()
    paths = LoopPaths.resolve(args.root)
    policy = OrchestrationPolicy.load(paths)
    tasks = load_manifest(manifest)
    detach = bool(getattr(args, "detach", False))
    explicit_wait = bool(getattr(args, "wait_all", False))
    if detach and explicit_wait:
        raise WaveError("--detach and --wait-all are mutually exclusive")
    # Parent-bound waves restore the Fable/native wait-all contract by
    # default.  Unparented operational waves retain the old detached behavior
    # unless the caller opts into --wait-all explicitly.
    wait_all = explicit_wait or (
        not detach and any(task.get("parent_session_id") for task in tasks))
    interval = max(0.0, args.spawn_interval_ms / 1000.0)
    results: list[dict[str, Any]] = []
    dispatcher = DispatcherV2(paths)
    for index, task in enumerate(tasks, 1):
        task_id = str(task["task_id"])
        if task.get("packet_id") is not None:
            packet_id = str(task["packet_id"])
            role = str(task.get("role") or "worker")
            ledger = read_json(paths.ledger, {"packets": {}}) or {"packets": {}}
            entry = (ledger.get("packets") or {}).get(packet_id)
            allowed_states = {"DISPATCHABLE"}
            if not isinstance(entry, dict) or entry.get("state") not in allowed_states:
                results.append({"task_id": task["task_id"],
                                "status": "ledger_state_blocked",
                                "packet_id": packet_id,
                                "ledger_state": (entry or {}).get("state")
                                if isinstance(entry, dict) else None})
                continue
            expected_model = resolve_role_pin(role, paths, policy).model
            prior = recover_live_supervisor(paths.data, packet_id)
            if prior.get("state") in ACTIVE and not (
                    process_alive(prior.get("supervisor_pid"),
                                  prior.get("supervisor_proc_start_ticks"))
                    and process_alive(prior.get("os_pid"),
                                      prior.get("worker_proc_start_ticks"))):
                results.append({"task_id": task["task_id"],
                                "status": "stale_active_roster",
                                "packet_id": packet_id,
                                "run_id": prior.get("run_id")})
                continue
            if prior.get("state") in ACTIVE and (
                    prior.get("role") != role or prior.get("model") != expected_model):
                results.append({"task_id": task["task_id"],
                                "status": "active_route_conflict",
                                "packet_id": packet_id,
                                "observed_role": prior.get("role"),
                                "observed_model": prior.get("model")})
                continue
            if prior.get("state") == "running":
                results.append({"task_id": task["task_id"], "status": "already_active",
                                "packet_id": packet_id, "run_id": prior.get("run_id")})
                continue
            if prior.get("state") == "starting":
                prior_run = str(prior.get("run_id") or "")
                if prior_run and wait_observed(paths.data, packet_id, prior_run,
                                               args.observe_timeout):
                    results.append({"task_id": task["task_id"],
                                    "status": "already_active",
                                    "packet_id": packet_id, "run_id": prior_run})
                else:
                    final = roster_item(paths.data, packet_id)
                    results.append({"task_id": task["task_id"],
                                    "status": str(final.get("state") or "initializing"),
                                    "packet_id": packet_id, "run_id": prior_run,
                                    "failure": final.get("failure")})
                continue
            if args.dry_run:
                rc = dispatcher.dispatch([packet_id], role=role, dry_run=True,
                                         wave_idx=index - 1)
                results.append({"task_id": task["task_id"],
                                "status": "dry_run" if rc == 0 else "dispatch_refused",
                                "packet_id": packet_id, "role": role})
                continue
            # Backoff is a birth gate, not a status/read-only gate: dry-runs
            # and already-active generations above remain observable.
            if not provider_birth_allowed(paths.root, expected_model):
                results.append({"task_id": task_id, "status": "provider_backoff",
                                "model": expected_model})
                continue
            if index > 1 and interval:
                time.sleep(interval)
            if index == 1 or (index - 1) % max(1, args.health_every) == 0:
                if not opencodex_healthy():
                    results.append({"task_id": task["task_id"],
                                    "status": "health_blocked",
                                    "packet_id": packet_id})
                    continue
            prior_run = str(prior.get("run_id") or "")
            rc = dispatcher.dispatch([packet_id], role=role, dry_run=False,
                                     wave_idx=index - 1)
            fresh = (wait_generation_change(paths.data, packet_id, prior_run,
                                            args.observe_timeout)
                     if rc == 0 else roster_item(paths.data, packet_id))
            run_id = str(fresh.get("run_id") or "")
            if rc == 0 and run_id and run_id != prior_run and wait_observed(
                    paths.data, packet_id, run_id, args.observe_timeout):
                results.append({"task_id": task["task_id"], "status": "running",
                                "packet_id": packet_id, "run_id": run_id})
            else:
                final = roster_item(paths.data, packet_id)
                results.append({"task_id": task["task_id"],
                                "status": ("dispatch_refused" if rc else
                                           str(final.get("state") or "unobserved")),
                                "packet_id": packet_id, "run_id": run_id,
                                "failure": final.get("failure")})
            continue
        packet_id, run_id, supervisor, worker, report_dir = build_commands(
            task, manifest, paths, policy, args.timeout, index)
        prior = recover_live_supervisor(paths.data, packet_id)
        if prior.get("state") == "completed":
            results.append({"task_id": task["task_id"], "status": "already_completed",
                            "packet_id": packet_id, "run_id": prior.get("run_id")})
            continue
        if prior.get("state") == "running":
            results.append({"task_id": task["task_id"], "status": "already_active",
                            "packet_id": packet_id, "run_id": prior.get("run_id")})
            continue
        if prior.get("state") == "starting":
            prior_run = str(prior.get("run_id") or "")
            if prior_run and wait_observed(paths.data, packet_id, prior_run,
                                           args.observe_timeout):
                results.append({"task_id": task["task_id"], "status": "already_active",
                                "packet_id": packet_id, "run_id": prior_run})
            else:
                final = roster_item(paths.data, packet_id)
                results.append({"task_id": task["task_id"],
                                "status": str(final.get("state") or "initializing"),
                                "packet_id": packet_id, "run_id": prior_run,
                                "failure": final.get("failure")})
            continue
        if args.dry_run:
            results.append({"task_id": task["task_id"], "status": "dry_run",
                            "packet_id": packet_id, "model": worker[worker.index("-m") + 1]})
            continue
        expected_model = worker[worker.index("-m") + 1]
        if not provider_birth_allowed(paths.root, expected_model):
            results.append({"task_id": task_id, "status": "provider_backoff",
                            "packet_id": packet_id, "model": expected_model})
            continue
        if index > 1 and interval:
            time.sleep(interval)
        if index == 1 or (index - 1) % max(1, args.health_every) == 0:
            if not opencodex_healthy():
                results.append({"task_id": task["task_id"], "status": "health_blocked",
                                "packet_id": packet_id})
                continue
        supervisor_pid = launch_supervisor(
            supervisor, paths.root, report_dir / "supervisor.log")
        if wait_observed(paths.data, packet_id, run_id, args.observe_timeout):
            results.append({"task_id": task["task_id"], "status": "running",
                            "packet_id": packet_id, "run_id": run_id,
                            "supervisor_pid": supervisor_pid})
        else:
            # Unknown is deliberately not counted as a successful handoff and
            # must not clear any external refill debt.  Do not auto-retry: the
            # supervisor may still be starting, and retrying could duplicate.
            final = roster_item(paths.data, packet_id)
            results.append({"task_id": task["task_id"],
                            "status": str(final.get("state") or "unobserved"),
                            "packet_id": packet_id, "run_id": run_id,
                            "supervisor_pid": supervisor_pid,
                            "failure": final.get("failure")})
    if wait_all and not args.dry_run:
        wait_for_terminal(paths.data, results, args.timeout + 30.0)
    print(json.dumps({"manifest": str(manifest), "target_requested": len(tasks),
                      "observed_running": sum(r["status"] in {"running", "already_active"}
                                              for r in results),
                      "wait_all": wait_all,
                      "results": results}, ensure_ascii=False))
    return 0 if all(r["status"] in {"running", "already_active", "already_completed",
                                       "completed", "dry_run"}
                    for r in results) else 3


def parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(description="Launch a lifecycle-visible headless Codex wave")
    ap.add_argument("--manifest", type=Path, required=True)
    ap.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    ap.add_argument("--timeout", type=float, default=1800.0)
    ap.add_argument("--observe-timeout", type=float, default=5.0)
    ap.add_argument("--spawn-interval-ms", type=int, default=1000)
    ap.add_argument("--health-every", type=int, default=8)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--wait-all", action="store_true",
                    help="wait for all observed generations to reach terminal state")
    ap.add_argument("--detach", action="store_true",
                    help="return after birth observation; only for intentional background waves")
    return ap


if __name__ == "__main__":
    raise SystemExit(run(parser().parse_args()))

#!/usr/bin/env python3
"""Bridge spawn_agents_on_csv results into generation-aware LOOP events."""
from __future__ import annotations

import argparse
import csv
import hashlib
import json
import os
import re
import sys
import time
from pathlib import Path

from lifecycle_supervisor import Store, publish_report


PACKET_ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,95}\Z")
SUCCESS = {"done", "completed", "ok", "success", "passed"}


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def write_stamp(path: Path, batch_csv: Path, results_csv: Path,
                summary: dict[str, int]) -> None:
    result_stat = results_csv.stat()
    doc = {
        "schema": "codex-loop-csv-reconcile-stamp/v1",
        "batch_csv": str(batch_csv.resolve()),
        "batch_sha256": sha256(batch_csv),
        "results_csv": str(results_csv.resolve()),
        "results_sha256": sha256(results_csv),
        "results_mtime_ns": result_stat.st_mtime_ns,
        "results_size": result_stat.st_size,
        "summary": summary,
        "exit": 1 if summary["failed"] else 0,
        "ran_at": time.time(),
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp-%d" % os.getpid())
    try:
        with tmp.open("w", encoding="utf-8") as handle:
            json.dump(doc, handle, ensure_ascii=False, indent=2, sort_keys=True)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp, path)
    finally:
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass


def rows(path: Path) -> list[dict[str, str]]:
    try:
        with path.open(encoding="utf-8", newline="") as handle:
            return list(csv.DictReader(handle))
    except OSError as exc:
        raise RuntimeError("CSV unreadable: %s: %s" % (path, exc)) from exc


def run(batch_csv: Path, results_csv: Path, data_dir: Path) -> dict[str, int]:
    batch = rows(batch_csv)
    results = rows(results_csv)
    try:
        ledger = json.loads((data_dir / "progress_ledger.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        ledger = {"packets": {}}
    by_id: dict[str, dict[str, str]] = {}
    for row in results:
        pid = row.get("packet_id") or row.get("id") or ""
        if pid in by_id:
            raise RuntimeError("duplicate CSV result packet_id: %s" % pid)
        by_id[pid] = row
    expected_ids = {row.get("packet_id") or "" for row in batch}
    extras = sorted(set(by_id) - expected_ids)
    if extras:
        raise RuntimeError("results contain packet ids absent from batch: %s" % extras)
    store = Store(data_dir.resolve())
    summary = {"completed": 0, "failed": 0}
    for expected in batch:
        pid = expected.get("packet_id") or ""
        if not PACKET_ID_RE.fullmatch(pid):
            raise RuntimeError("invalid packet id in batch: %r" % pid)
        run_id = expected.get("run_id") or ""
        try:
            attempt = int(expected.get("attempt", "0"))
        except ValueError as exc:
            raise RuntimeError("invalid attempt for %s" % pid) from exc
        current_attempt = int(ledger.get("packets", {}).get(pid, {}).get("attempts", attempt) or 0)
        if attempt < current_attempt:
            continue
        result = by_id.get(pid)
        status = str((result or {}).get("status") or "").strip().lower()
        if result is not None and status in SUCCESS:
            source = Path(expected.get("local_report") or "")
            worktree = Path(expected.get("worktree") or "")
            destination = data_dir / "reports" / pid / "report.json"
            if not source.is_file():
                status = "missing_report"
            else:
                try:
                    report = json.loads(source.read_text(encoding="utf-8"))
                except (OSError, ValueError) as exc:
                    raise RuntimeError("report unreadable for %s: %s" % (pid, exc)) from exc
                if report.get("packet_id") not in (None, pid):
                    raise RuntimeError("report packet_id mismatch for %s" % pid)
                publish_report(source, destination, worktree, data_dir)
                store.append_event_once(pid, run_id, attempt, "subagent_stop",
                    {"source": "csv_reconcile", "status": status})
                summary["completed"] += 1
                continue
        why = "csv_result_missing" if result is None else (
              "missing_report" if status == "missing_report" else "csv_worker_failed")
        store.append_event_once(pid, run_id, attempt, "exec_failed",
            {"source": "csv_reconcile", "why": why,
             "status": status, "summary": str((result or {}).get("summary") or "")[:500]})
        summary["failed"] += 1
    return summary


def main() -> int:
    parser = argparse.ArgumentParser(description="Reconcile spawn_agents_on_csv output")
    parser.add_argument("--batch-csv", type=Path, required=True)
    parser.add_argument("--results-csv", type=Path, required=True)
    parser.add_argument("--data-dir", type=Path, required=True)
    parser.add_argument("--stamp", type=Path,
                        help="write an atomic result-fingerprint stamp after complete reconciliation")
    args = parser.parse_args()
    summary = run(args.batch_csv, args.results_csv, args.data_dir)
    if args.stamp:
        write_stamp(args.stamp, args.batch_csv, args.results_csv, summary)
        summary["stamp"] = str(args.stamp.resolve())
    try:
        from orchestration_epilogue import run_epilogue
        run_epilogue(args.data_dir.parent, source="csv_reconcile")
    except Exception as exc:
        summary["epilogue_error"] = "%s: %s" % (type(exc).__name__, exc)
    print(json.dumps(summary, sort_keys=True))
    return 1 if summary["failed"] else 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Plan or safely apply stale Desktop spawn-edge reconciliation.

Default operation is strictly read-only.  ``--apply`` is an explicit offline
maintenance action: it refuses while Codex Desktop processes are present,
backs up the WAL database through SQLite's backup API, verifies the expected
schema, and performs only the idempotent transition ``open -> closed`` for
children whose shadow roster has strong terminal evidence.
"""
from __future__ import annotations

import argparse
import csv
import hashlib
import json
import os
import sqlite3
import subprocess
import time
from pathlib import Path
from typing import Any, Callable


EXPECTED_EDGE_COLUMNS = {"parent_thread_id", "child_thread_id", "status"}
STRONG_TERMINAL = {"terminal"}


class ReconcileError(RuntimeError):
    pass


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def state_digest(path: Path) -> str:
    """Hash the complete durable SQLite state, including an active WAL."""
    digest = hashlib.sha256()
    for candidate in (path, Path(str(path) + "-wal")):
        digest.update(candidate.name.encode("utf-8"))
        if not candidate.exists():
            digest.update(b"\0missing\0")
            continue
        digest.update(str(candidate.stat().st_size).encode("ascii") + b"\0")
        with candidate.open("rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(block)
    return digest.hexdigest()


def connect_readonly(path: Path) -> sqlite3.Connection:
    return sqlite3.connect(path.resolve().as_uri() + "?mode=ro", uri=True, timeout=2.0)


def edge_schema(conn: sqlite3.Connection) -> set[str]:
    rows = conn.execute("PRAGMA table_info(thread_spawn_edges)").fetchall()
    return {str(row[1]) for row in rows}


def terminal_agents(roster_path: Path) -> dict[str, dict[str, Any]]:
    try:
        roster = json.loads(roster_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise ReconcileError("native roster unreadable: %s" % exc) from exc
    agents = roster.get("agents", {})
    if not isinstance(agents, dict):
        raise ReconcileError("native roster agents must be an object")
    return {str(agent_id): item for agent_id, item in agents.items()
            if isinstance(item, dict) and item.get("status") in STRONG_TERMINAL and
            str(item.get("terminal_reason", "")).startswith(("SubagentStop", "rollout_")) and
            (item.get("host_close_confirmed_at") or
             str(item.get("terminal_reason", "")).startswith("rollout_thread_closed"))}


def snapshot(state_db: Path) -> dict[str, Any]:
    with connect_readonly(state_db) as conn:
        columns = edge_schema(conn)
        if columns != EXPECTED_EDGE_COLUMNS:
            raise ReconcileError("unexpected thread_spawn_edges schema: %s" % sorted(columns))
        rows = conn.execute(
            "SELECT parent_thread_id, child_thread_id, status FROM thread_spawn_edges ORDER BY child_thread_id"
        ).fetchall()
    return {"db_sha256": sha256(state_db), "db_state_digest": state_digest(state_db),
            "schema_columns": sorted(columns),
            "edge_count": len(rows),
            "edges": [{"parent_thread_id": row[0], "child_thread_id": row[1], "status": row[2]}
                      for row in rows]}


def plan(state_db: Path, roster_path: Path) -> dict[str, Any]:
    snap = snapshot(state_db)
    terminal = terminal_agents(roster_path)
    candidates = []
    for edge in snap["edges"]:
        child = str(edge["child_thread_id"])
        if edge["status"] == "open" and child in terminal:
            item = terminal[child]
            candidates.append({**edge, "task_name": item.get("task_name"),
                               "terminal_reason": item.get("terminal_reason")})
    return {"schema": "codex-loop-desktop-edge-plan/v1", "generated_at": time.time(),
            "state_db": str(state_db.resolve()), "roster": str(roster_path.resolve()),
            "db_sha256": snap["db_sha256"], "db_state_digest": snap["db_state_digest"],
            "roster_sha256": sha256(roster_path), "edge_count": snap["edge_count"],
            "candidates": candidates,
            "candidate_count": len(candidates), "mode": "dry-run"}


def desktop_running() -> bool:
    names = {"chatgpt.exe", "codex.exe", "codex-code-mode-host.exe",
             "chatgpt", "codex", "codex-code-mode-host"}
    if os.name == "nt":
        result = subprocess.run(["tasklist", "/FO", "CSV", "/NH"], capture_output=True,
                                text=True, timeout=10, check=False)
        if result.returncode != 0:
            # Unknown liveness must fail closed for a write operation.
            return True
        for row in csv.reader(result.stdout.splitlines()):
            if row and row[0].strip().lower() in names:
                return True
        return False
    result = subprocess.run(["ps", "-eo", "comm="], capture_output=True, text=True,
                            timeout=10, check=False)
    return result.returncode != 0 or any(Path(line.strip()).name.lower() in names
                                         for line in result.stdout.splitlines())


def verify_backup(target: Path, expected_edge_count: int) -> dict[str, Any]:
    with sqlite3.connect(str(target)) as conn:
        columns = edge_schema(conn)
        quick_check = conn.execute("PRAGMA quick_check").fetchone()[0]
        backup_edges = conn.execute("SELECT COUNT(*) FROM thread_spawn_edges").fetchone()[0]
    if columns != EXPECTED_EDGE_COLUMNS:
        raise ReconcileError("backup schema verification failed")
    if quick_check != "ok" or backup_edges != expected_edge_count:
        raise ReconcileError("backup integrity/row-count verification failed")
    return {"quick_check": quick_check, "edge_count": backup_edges}


def sqlite_backup(state_db: Path, backup_dir: Path,
                  expected_edge_count: int | None = None) -> dict[str, Any]:
    backup_dir.mkdir(parents=True, exist_ok=True)
    target = backup_dir / ("state_5-%d.sqlite" % int(time.time() * 1000))
    source = connect_readonly(state_db)
    destination = sqlite3.connect(str(target))
    try:
        source_edges = source.execute("SELECT COUNT(*) FROM thread_spawn_edges").fetchone()[0]
        source.backup(destination)
    finally:
        destination.close(); source.close()
    if expected_edge_count is not None and source_edges != expected_edge_count:
        raise ReconcileError("source row count changed after dry-run snapshot")
    verified = verify_backup(target, source_edges)
    return {"path": str(target.resolve()), "sha256": sha256(target),
            "bytes": target.stat().st_size, **verified}


def apply_plan(plan_doc: dict[str, Any], backup_dir: Path,
               is_desktop_running: Callable[[], bool] = desktop_running) -> dict[str, Any]:
    if is_desktop_running():
        raise ReconcileError("Codex Desktop is running or liveness is unknown; refusing state DB write")
    state_db = Path(plan_doc["state_db"])
    roster_path = Path(plan_doc["roster"])
    if state_digest(state_db) != plan_doc.get("db_state_digest"):
        raise ReconcileError("state DB changed after dry-run snapshot")
    if sha256(roster_path) != plan_doc.get("roster_sha256"):
        raise ReconcileError("native roster changed after dry-run snapshot")
    terminal = terminal_agents(roster_path)
    for item in plan_doc.get("candidates", []):
        if str(item.get("child_thread_id")) not in terminal:
            raise ReconcileError("candidate lost strong terminal/host-close evidence")
    backup = sqlite_backup(state_db, backup_dir, int(plan_doc.get("edge_count", -1)))
    if is_desktop_running():
        raise ReconcileError("Codex Desktop started during backup; refusing state DB write")
    if state_digest(state_db) != plan_doc.get("db_state_digest"):
        raise ReconcileError("state DB changed during backup")
    changed = 0
    conn = sqlite3.connect(str(state_db), timeout=5.0, isolation_level=None)
    try:
        if edge_schema(conn) != EXPECTED_EDGE_COLUMNS:
            raise ReconcileError("schema changed before apply")
        conn.execute("BEGIN IMMEDIATE")
        for item in plan_doc.get("candidates", []):
            cursor = conn.execute(
                "UPDATE thread_spawn_edges SET status='closed' "
                "WHERE child_thread_id=? AND status='open'",
                (item["child_thread_id"],))
            changed += cursor.rowcount
        conn.execute("COMMIT")
    except BaseException:
        try: conn.execute("ROLLBACK")
        except sqlite3.Error: pass
        raise
    finally:
        conn.close()
    return {**plan_doc, "mode": "applied", "changed": changed, "backup": backup,
            "applied_at": time.time(), "post_db_sha256": sha256(state_db),
            "post_db_state_digest": state_digest(state_db)}


def main() -> int:
    ap = argparse.ArgumentParser(description="Dry-run/offline stale Desktop edge reconciliation")
    ap.add_argument("--state-db", type=Path, required=True)
    ap.add_argument("--roster", type=Path, required=True)
    ap.add_argument("--out", type=Path)
    ap.add_argument("--apply", action="store_true")
    ap.add_argument("--backup-dir", type=Path)
    args = ap.parse_args()
    doc = plan(args.state_db, args.roster)
    if args.apply:
        if not args.backup_dir:
            raise ReconcileError("--backup-dir is required with --apply")
        doc = apply_plan(doc, args.backup_dir)
    rendered = json.dumps(doc, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    if args.out:
        args.out.parent.mkdir(parents=True, exist_ok=True)
        args.out.write_text(rendered, encoding="utf-8")
    print(rendered, end="")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
